ECAI_POSTGRES_SCHEMA = r"""
CREATE TABLE IF NOT EXISTS review_cycle (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    review_cycle_id TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Closed','Archived')),
    started_at TEXT NOT NULL,
    closed_at TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_review_cycle_one_active
ON review_cycle(status) WHERE status = 'Active';

CREATE TABLE IF NOT EXISTS relationship (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    relationship_id TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL UNIQUE,
    country TEXT,
    sector TEXT,
    external_rating TEXT,
    outlook TEXT,
    score DOUBLE PRECISION,
    attention_rating TEXT,
    primary_driver TEXT,
    recommended_action TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS portfolio_signal (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    signal_id TEXT NOT NULL UNIQUE,
    review_cycle_id BIGINT NOT NULL REFERENCES review_cycle(id),
    pattern TEXT NOT NULL,
    severity TEXT NOT NULL,
    interpretation TEXT,
    management_question TEXT,
    status TEXT NOT NULL DEFAULT 'Open',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS portfolio_signal_relationship (
    portfolio_signal_id BIGINT NOT NULL REFERENCES portfolio_signal(id) ON DELETE CASCADE,
    relationship_id BIGINT NOT NULL REFERENCES relationship(id),
    PRIMARY KEY (portfolio_signal_id, relationship_id)
);

CREATE TABLE IF NOT EXISTS review_item (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    review_item_id TEXT NOT NULL UNIQUE,
    review_cycle_id BIGINT NOT NULL REFERENCES review_cycle(id),
    relationship_id BIGINT REFERENCES relationship(id),
    portfolio_signal_id BIGINT REFERENCES portfolio_signal(id),
    title TEXT NOT NULL,
    management_question TEXT,
    recommendation TEXT,
    expected_outcome TEXT,
    status TEXT NOT NULL DEFAULT 'Open',
    source TEXT NOT NULL DEFAULT 'Relationship Review',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    closed_at TEXT
);

CREATE TABLE IF NOT EXISTS decision (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    decision_id TEXT NOT NULL UNIQUE,
    review_item_id BIGINT NOT NULL REFERENCES review_item(id),
    relationship_id BIGINT NOT NULL REFERENCES relationship(id),
    review_cycle_id BIGINT NOT NULL REFERENCES review_cycle(id),
    decision_date TEXT NOT NULL,
    original_recommendation TEXT NOT NULL,
    management_decision TEXT NOT NULL CHECK (management_decision IN ('Approved','Modified','Deferred','Rejected')),
    final_action TEXT NOT NULL,
    rationale TEXT NOT NULL,
    decision_owner TEXT NOT NULL,
    execution_required SMALLINT NOT NULL DEFAULT 0 CHECK (execution_required IN (0,1)),
    lifecycle_status TEXT NOT NULL DEFAULT 'Open',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    closed_at TEXT
);

CREATE INDEX IF NOT EXISTS ix_decision_relationship ON decision(relationship_id, id DESC);
CREATE INDEX IF NOT EXISTS ix_decision_review_item ON decision(review_item_id, id DESC);

CREATE TABLE IF NOT EXISTS execution_action (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    execution_action_id TEXT NOT NULL UNIQUE,
    decision_id BIGINT REFERENCES decision(id),
    review_item_id BIGINT REFERENCES review_item(id),
    relationship_id BIGINT NOT NULL REFERENCES relationship(id),
    source TEXT NOT NULL,
    score DOUBLE PRECISION,
    attention_rating TEXT,
    action TEXT NOT NULL,
    owner TEXT NOT NULL,
    priority TEXT,
    due TEXT,
    status TEXT NOT NULL,
    progress_pct INTEGER NOT NULL DEFAULT 0 CHECK (progress_pct BETWEEN 0 AND 100),
    follow_up_cadence TEXT,
    sla_status TEXT,
    impact TEXT,
    next_step TEXT,
    closure_criteria TEXT,
    outcome_status TEXT NOT NULL DEFAULT 'Pending',
    outcome TEXT NOT NULL DEFAULT 'Pending',
    closure_evidence TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    closed_at TEXT,
    CHECK (
        (source = 'Management Decision' AND decision_id IS NOT NULL)
        OR (source = 'Migrated v10' AND decision_id IS NULL)
    )
);

CREATE INDEX IF NOT EXISTS ix_execution_relationship ON execution_action(relationship_id, id DESC);
CREATE INDEX IF NOT EXISTS ix_execution_decision ON execution_action(decision_id);
CREATE INDEX IF NOT EXISTS ix_execution_status ON execution_action(status);

CREATE TABLE IF NOT EXISTS audit_event (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    audit_event_id TEXT NOT NULL UNIQUE,
    entity_type TEXT NOT NULL,
    entity_id TEXT NOT NULL,
    relationship_id BIGINT REFERENCES relationship(id),
    event_type TEXT NOT NULL,
    event_timestamp TEXT NOT NULL,
    actor TEXT,
    payload_json TEXT NOT NULL DEFAULT '{}'
);

CREATE INDEX IF NOT EXISTS ix_audit_entity ON audit_event(entity_type, entity_id, id DESC);
CREATE INDEX IF NOT EXISTS ix_audit_relationship ON audit_event(relationship_id, id DESC);


CREATE INDEX IF NOT EXISTS ix_portfolio_signal_cycle_status
ON portfolio_signal(review_cycle_id, status, id);

CREATE UNIQUE INDEX IF NOT EXISTS ux_review_item_relationship_cycle
ON review_item(review_cycle_id, relationship_id)
WHERE source = 'Relationship Review' AND relationship_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS ux_review_item_portfolio_cycle
ON review_item(review_cycle_id, portfolio_signal_id)
WHERE source = 'Portfolio Intelligence' AND portfolio_signal_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS ux_execution_one_action_per_decision
ON execution_action(decision_id)
WHERE source = 'Management Decision' AND decision_id IS NOT NULL;


-- Stage 1-E.1J additive intelligence foundation.
CREATE TABLE IF NOT EXISTS intelligence_methodology (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    methodology_id TEXT NOT NULL UNIQUE,
    methodology_code TEXT NOT NULL,
    methodology_name TEXT NOT NULL,
    version TEXT NOT NULL,
    domain TEXT NOT NULL,
    product TEXT NOT NULL,
    description TEXT,
    required_inputs_json TEXT NOT NULL DEFAULT '[]',
    optional_inputs_json TEXT NOT NULL DEFAULT '[]',
    outputs_json TEXT NOT NULL DEFAULT '[]',
    critical_inputs_json TEXT NOT NULL DEFAULT '[]',
    effective_from TEXT,
    effective_to TEXT,
    status TEXT NOT NULL DEFAULT 'ACTIVE',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    UNIQUE(methodology_code, version)
);

CREATE TABLE IF NOT EXISTS intelligence_evidence (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    evidence_id TEXT NOT NULL UNIQUE,
    relationship_id BIGINT NOT NULL REFERENCES relationship(id),
    review_cycle_id BIGINT NOT NULL REFERENCES review_cycle(id),
    methodology_id BIGINT REFERENCES intelligence_methodology(id),
    metric_code TEXT NOT NULL,
    metric_name TEXT,
    value_numeric DOUBLE PRECISION,
    value_text TEXT,
    unit TEXT,
    currency TEXT,
    evidence_type TEXT NOT NULL CHECK (evidence_type IN ('FACT','DERIVED_FACT','ASSUMPTION')),
    source_type TEXT,
    source_name TEXT,
    source_reference TEXT,
    effective_date TEXT,
    as_of_date TEXT,
    confidence TEXT NOT NULL CHECK (confidence IN ('HIGH','MEDIUM','LOW')),
    owner TEXT,
    review_date TEXT,
    created_at TEXT NOT NULL,
    CHECK (value_numeric IS NOT NULL OR value_text IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS ix_intel_evidence_relationship
ON intelligence_evidence(relationship_id, review_cycle_id, metric_code, id DESC);

CREATE TABLE IF NOT EXISTS intelligence_calculation (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    calculation_id TEXT NOT NULL UNIQUE,
    relationship_id BIGINT NOT NULL REFERENCES relationship(id),
    review_cycle_id BIGINT NOT NULL REFERENCES review_cycle(id),
    methodology_id BIGINT NOT NULL REFERENCES intelligence_methodology(id),
    metric_code TEXT NOT NULL,
    metric_name TEXT,
    formula_code TEXT NOT NULL,
    formula_version TEXT NOT NULL,
    formula_expression TEXT NOT NULL,
    input_evidence_ids_json TEXT NOT NULL DEFAULT '[]',
    output_value_numeric DOUBLE PRECISION NOT NULL,
    unit TEXT,
    currency TEXT,
    calculated_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS ix_intel_calc_relationship
ON intelligence_calculation(relationship_id, review_cycle_id, metric_code, id DESC);

CREATE TABLE IF NOT EXISTS wallet_assessment (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    assessment_id TEXT NOT NULL UNIQUE,
    relationship_id BIGINT NOT NULL REFERENCES relationship(id),
    review_cycle_id BIGINT NOT NULL REFERENCES review_cycle(id),
    methodology_id BIGINT NOT NULL REFERENCES intelligence_methodology(id),

    product TEXT NOT NULL,
    effective_date TEXT,
    currency TEXT,
    geographic_scope TEXT NOT NULL DEFAULT 'Global',
    time_horizon TEXT NOT NULL DEFAULT 'N/A',

    evidence_ids_json TEXT NOT NULL DEFAULT '[]',
    calculation_ids_json TEXT NOT NULL DEFAULT '[]',

    addressable_notional DOUBLE PRECISION,
    captured_notional DOUBLE PRECISION,
    notional_penetration DOUBLE PRECISION,

    estimated_wallet_revenue DOUBLE PRECISION,
    actual_bank_revenue DOUBLE PRECISION,
    revenue_share_of_wallet DOUBLE PRECISION,
    revenue_wallet_gap DOUBLE PRECISION,

    notional_completeness TEXT NOT NULL DEFAULT 'PARTIAL'
        CHECK (notional_completeness IN ('COMPLETE','PARTIAL')),
    revenue_wallet_completeness TEXT NOT NULL DEFAULT 'PARTIAL'
        CHECK (revenue_wallet_completeness IN ('COMPLETE','PARTIAL')),

    confidence TEXT CHECK (confidence IN ('HIGH','MEDIUM','LOW')),
    confidence_explanation TEXT,

    status TEXT NOT NULL DEFAULT 'DRAFT'
        CHECK (status IN ('DRAFT','VALIDATED','PUBLISHED','SUPERSEDED')),
    publication_result TEXT
        CHECK (publication_result IN ('PUBLISH','HOLD','REJECT')),
    quality_gate_json TEXT NOT NULL DEFAULT '{}',

    -- Stage 1-E.2A.7 additive Structural Lending v1.0 interpretation snapshot.
    wallet_scope TEXT,
    wallet_coverage TEXT,
    capex_component_status TEXT,
    refinancing_component_status TEXT,
    capture_component_status TEXT,
    bank_capex_notional DOUBLE PRECISION,
    bank_refinancing_notional DOUBLE PRECISION,
    raw_wallet_gap DOUBLE PRECISION,
    positive_wallet_gap DOUBLE PRECISION,
    capture_comparability_status TEXT,
    test_only SMALLINT NOT NULL DEFAULT 0,
    economic_interpretation_json TEXT NOT NULL DEFAULT '{}',

    created_at TEXT NOT NULL,
    validated_at TEXT,
    published_at TEXT,
    superseded_at TEXT,
    published_by TEXT,
    publication_mode TEXT
);

CREATE INDEX IF NOT EXISTS ix_wallet_assessment_relationship
ON wallet_assessment(relationship_id, product, id DESC);

CREATE UNIQUE INDEX IF NOT EXISTS ux_wallet_one_current_published
ON wallet_assessment(relationship_id, product, geographic_scope, time_horizon)
WHERE status = 'PUBLISHED';

CREATE TABLE IF NOT EXISTS ecai_system_metadata (
    metadata_key TEXT PRIMARY KEY,
    metadata_value TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE OR REPLACE FUNCTION ecai_audit_event_append_only()
RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'AuditEvent is append-only';
END;
$$ LANGUAGE plpgsql;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_audit_event_no_update') THEN
        CREATE TRIGGER trg_audit_event_no_update
        BEFORE UPDATE ON audit_event
        FOR EACH ROW EXECUTE FUNCTION ecai_audit_event_append_only();
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_audit_event_no_delete') THEN
        CREATE TRIGGER trg_audit_event_no_delete
        BEFORE DELETE ON audit_event
        FOR EACH ROW EXECUTE FUNCTION ecai_audit_event_append_only();
    END IF;
END $$;
"""




# =============================================================================
# STAGE 1-E.2A.7 — ADDITIVE WALLET_ASSESSMENT SCHEMA MIGRATION
# =============================================================================
def _db_stage1e2_migrate_wallet_assessment_columns(conn: _DBConnection):
    """Add Stage 1-E.2 wallet/evidence fields without rewriting historical rows.

    Stage 1-E.1J and Structural Lending WAL-* history remains intact. New columns
    are nullable/defaulted, so historical economic interpretations remain frozen.
    """
    columns = [
        ("wallet_scope", "TEXT"),
        ("wallet_coverage", "TEXT"),
        ("capex_component_status", "TEXT"),
        ("refinancing_component_status", "TEXT"),
        ("capture_component_status", "TEXT"),
        ("bank_capex_notional", "REAL" if conn.backend == "sqlite" else "DOUBLE PRECISION"),
        ("bank_refinancing_notional", "REAL" if conn.backend == "sqlite" else "DOUBLE PRECISION"),
        ("raw_wallet_gap", "REAL" if conn.backend == "sqlite" else "DOUBLE PRECISION"),
        ("positive_wallet_gap", "REAL" if conn.backend == "sqlite" else "DOUBLE PRECISION"),
        ("capture_comparability_status", "TEXT"),
        ("test_only", "INTEGER NOT NULL DEFAULT 0" if conn.backend == "sqlite" else "SMALLINT NOT NULL DEFAULT 0"),
        ("economic_interpretation_json", "TEXT NOT NULL DEFAULT '{}'"),
        # Stage 1-E.2B.6 additive Cash & Liquidity interpretation fields.
        ("liquidity_component_status", "TEXT"),
        ("relevant_cash_pool", "REAL" if conn.backend == "sqlite" else "DOUBLE PRECISION"),
        ("forecast_bankable_liquidity_share", "REAL" if conn.backend == "sqlite" else "DOUBLE PRECISION"),
        ("liquidity_time_basis", "TEXT"),
    ]

    evidence_columns = [
        ("economic_perimeter", "TEXT"),
        ("geographic_scope", "TEXT"),
        ("time_basis", "TEXT"),
        ("rationale", "TEXT"),
    ]

    if conn.backend == "sqlite":
        existing = {row[1] for row in conn.execute("PRAGMA table_info(wallet_assessment)").fetchall()}
        for name, ddl in columns:
            if name not in existing:
                conn.execute(f"ALTER TABLE wallet_assessment ADD COLUMN {name} {ddl}")
        evidence_existing = {row[1] for row in conn.execute("PRAGMA table_info(intelligence_evidence)").fetchall()}
        for name, ddl in evidence_columns:
            if name not in evidence_existing:
                conn.execute(f"ALTER TABLE intelligence_evidence ADD COLUMN {name} {ddl}")
    else:
        for name, ddl in columns:
            conn.execute(f"ALTER TABLE wallet_assessment ADD COLUMN IF NOT EXISTS {name} {ddl}")
        for name, ddl in evidence_columns:
            conn.execute(f"ALTER TABLE intelligence_evidence ADD COLUMN IF NOT EXISTS {name} {ddl}")


def _db_init_schema_uncached():
    """Create/upgrade the EC-AI schema safely.

    PostgreSQL DDL touches shared system catalogs. Streamlit can briefly run two
    app reruns at the same time (for example immediately after Record Decision),
    so concurrent CREATE/CREATE OR REPLACE statements can raise
    ``tuple concurrently updated``. A PostgreSQL advisory transaction lock
    serializes schema bootstrap across all EC-AI sessions/workers. A small retry
    handles a catalog conflict already in flight when the new build starts.
    """
    schema = ECAI_POSTGRES_SCHEMA if ECAI_DB_BACKEND == "postgresql" else ECAI_SQLITE_SCHEMA
    max_attempts = 4 if ECAI_DB_BACKEND == "postgresql" else 1

    for attempt in range(1, max_attempts + 1):
        conn = _db_connect()
        try:
            if conn.backend == "postgresql":
                # Stable application-scoped lock key; held until commit/rollback.
                conn.execute("SELECT pg_advisory_xact_lock(?)", (831042026,))
            conn.executescript(schema)
            _db_stage1e2_migrate_wallet_assessment_columns(conn)
            _db_stage1e3_migrate_schema(conn)
            _db_stage1e4_migrate_schema(conn)
            _db_stage1e5_migrate_schema(conn)
            _db_stage1e6_migrate_schema(conn)
            if conn.backend == "sqlite":
                conn.execute(f"PRAGMA user_version = {ECAI_SCHEMA_VERSION}")
            conn.commit()
            return True
        except Exception as exc:
            try:
                conn.rollback()
            except Exception:
                pass
            transient = "tuple concurrently updated" in str(exc).lower()
            if conn.backend == "postgresql" and transient and attempt < max_attempts:
                time.sleep(0.35 * attempt)
                continue
            raise
        finally:
            conn.close()


@st.cache_resource(show_spinner=False)
def _db_init_schema_cached(backend: str, schema_version: int, database_identity: str):
    """Run DDL once per Streamlit worker/deployment, not on every widget rerun."""
    return _db_init_schema_uncached()


def _db_database_identity() -> str:
    # Never expose credentials in cache keys, logs or the UI.
    if ECAI_DB_BACKEND == "postgresql":
        return re.sub(r"://[^@]+@", "://***@", ECAI_DATABASE_URL)
    return os.path.abspath(ECAI_DB_PATH)


def _db_init_schema():
    return _db_init_schema_cached(ECAI_DB_BACKEND, ECAI_SCHEMA_VERSION, _db_database_identity())


def _db_slug(value: str) -> str:
    slug = re.sub(r"[^A-Z0-9]+", "-", str(value).upper()).strip("-")
    return slug or "UNKNOWN"


def _db_next_id(conn: _DBConnection, table: str, column: str, prefix: str, width: int = 4) -> str:
    """Allocate the next human-readable public ID safely.

    SQLite transactions are serialized with BEGIN IMMEDIATE. PostgreSQL needs an
    explicit transaction-scoped advisory lock so two Streamlit sessions cannot
    both calculate the same next DEC/ACT/AUD/REV/PRI identifier.
    """
    if conn.backend == "postgresql":
        lock_name = f"ecai-public-id:{table}:{column}:{prefix}"
        conn.execute("SELECT pg_advisory_xact_lock(hashtext(?))", (lock_name,))
    rows = conn.execute(f"SELECT {column} FROM {table} WHERE {column} LIKE ?", (f"{prefix}-%",)).fetchall()
    highest = 0
    for row in rows:
        value = str(row[0])
        match = re.match(rf"^{re.escape(prefix)}-(\d+)$", value)
        if match:
            highest = max(highest, int(match.group(1)))
    return f"{prefix}-{highest + 1:0{width}d}"


def _db_active_review_cycle(conn: _DBConnection) -> Any:
    row = conn.execute("SELECT * FROM review_cycle WHERE status='Active' ORDER BY id DESC LIMIT 1").fetchone()
    if row is None:
        now = _db_now()
        conn.execute(
            "INSERT INTO review_cycle(review_cycle_id,name,status,started_at,created_at,updated_at) VALUES (?,?,?,?,?,?)",
            ("RC-CURRENT", "Current Review", "Active", now, now, now),
        )
        row = conn.execute("SELECT * FROM review_cycle WHERE review_cycle_id='RC-CURRENT'").fetchone()
    return row


def _db_relationship_row(conn: _DBConnection, company: str) -> Any:
    """Resolve a relationship through its permanent Relationship ID first.

    Stage 1-D.3 makes Relationship the authoritative identity object. The UI may
    continue to pass the familiar company display name, but database joins are
    anchored to a stable REL-* key rather than treating the display name as the
    real key. A name lookup is retained only as a compatibility fallback for any
    pre-D.2B record.
    """
    relationship_key = f"REL-{_db_slug(company)}"
    rel = conn.execute(
        "SELECT * FROM relationship WHERE relationship_id=?",
        (relationship_key,),
    ).fetchone()
    if rel is None:
        rel = conn.execute("SELECT * FROM relationship WHERE name=?", (str(company),)).fetchone()
    if rel is None:
        raise ValueError(f"Relationship {company} is not registered in Stage 1-D.3.")
    return rel


def _db_list_relationship_registry(conn: _DBConnection | None = None) -> list[dict]:
    """Return the authoritative Relationship master used by the UI shell.

    Identity attributes (relationship_id/name/country/sector) are owned by the
    operational database. Rating/outlook and score/recommendation fields remain
    analytical snapshots that can be refreshed from the current intelligence
    dataset without changing identity.
    """
    owns_connection = conn is None
    if owns_connection:
        conn = _db_connect()
    try:
        rows = conn.execute(
            """SELECT id,relationship_id,name,country,sector,external_rating,outlook,
                      score,attention_rating,primary_driver,recommended_action,
                      created_at,updated_at
               FROM relationship
               WHERE relationship_id NOT IN ('REL-EC-AI-E3-VALIDATION-CO','REL-EC-AI-E4-VALIDATION-CO','REL-EC-AI-E5-VALIDATION-CO','REL-EC-AI-E5-FINAL-VALIDATION-CO','REL-EC-AI-E6-VALIDATION-CO')
               ORDER BY id"""
        ).fetchall()
        return [
            {
                "DB ID": int(r["id"]),
                "Relationship ID": r["relationship_id"],
                "Name": r["name"],
                "Country": r["country"] or "",
                "Sector": r["sector"] or "",
                "External Rating": r["external_rating"] or "",
                "Outlook": r["outlook"] or "",
                "Score": float(r["score"]) if r["score"] is not None else None,
                "Attention Rating": r["attention_rating"] or "",
                "Primary Driver": r["primary_driver"] or "",
                "Recommended Action": r["recommended_action"] or "",
                "Created": r["created_at"],
                "Last Updated": r["updated_at"],
            }
            for r in rows
        ]
    finally:
        if owns_connection:
            conn.close()


def _db_append_audit(
    conn: _DBConnection,
    *,
    entity_type: str,
    entity_id: str,
    relationship_id: int | None,
    event_type: str,
    actor: str | None,
    payload: dict | None = None,
    idempotency_key: str | None = None,
):
    # Stage 1-E.6.8C extends AuditEvent with an optional idempotency key. Existing
    # Stage 1-D/E callers remain unchanged; E.6 exact reruns can now be truly quiet.
    if idempotency_key:
        existing = conn.execute(
            "SELECT audit_event_id FROM audit_event WHERE idempotency_key=?",
            (idempotency_key,),
        ).fetchone()
        if existing is not None:
            return existing[0]
    audit_id = _db_next_id(conn, "audit_event", "audit_event_id", "AUD", width=6)
    conn.execute(
        """INSERT INTO audit_event(
               audit_event_id, entity_type, entity_id, relationship_id,
               event_type, event_timestamp, actor, payload_json, idempotency_key
           ) VALUES (?,?,?,?,?,?,?,?,?)""",
        (
            audit_id,
            entity_type,
            entity_id,
            relationship_id,
            event_type,
            _db_now(),
            actor or "EC-AI",
            json.dumps(payload or {}, ensure_ascii=False, default=str),
            idempotency_key,
        ),
    )
    return audit_id


# =============================================================================
# STAGE 1-E.1J — INTELLIGENCE FOUNDATION / LENDING WALLET v0.1
# =============================================================================
# Stage 1-C.10 UI remains unchanged. Stage 1-D Relationship and ReviewCycle
# remain authoritative. Only PUBLISHED assessments are eligible to feed future
# OpportunitySignal logic. No OpportunitySignal / AI reasoning is wired yet.

class EvidenceType(str, Enum):
    FACT = "FACT"
    DERIVED_FACT = "DERIVED_FACT"
    ASSUMPTION = "ASSUMPTION"


class ConfidenceLevel(str, Enum):
    HIGH = "HIGH"
    MEDIUM = "MEDIUM"
    LOW = "LOW"


class CompletenessStatus(str, Enum):
    COMPLETE = "COMPLETE"
    PARTIAL = "PARTIAL"


class AssessmentStatus(str, Enum):
    DRAFT = "DRAFT"
    VALIDATED = "VALIDATED"
    PUBLISHED = "PUBLISHED"
    SUPERSEDED = "SUPERSEDED"


class PublicationResult(str, Enum):
    PUBLISH = "PUBLISH"
    HOLD = "HOLD"
    REJECT = "REJECT"


@dataclass(frozen=True)
class EvidenceItem:
    metric_code: str
    evidence_type: EvidenceType
    confidence: ConfidenceLevel
    value_numeric: float | None = None
    value_text: str | None = None
    metric_name: str | None = None
    unit: str | None = None
    currency: str | None = None
    source_type: str | None = None
    source_name: str | None = None
    source_reference: str | None = None
    effective_date: str | None = None
    as_of_date: str | None = None
    owner: str | None = None
    review_date: str | None = None
    # Stage 1-E.2B additive evidence metadata. Optional so all historical
    # Stage 1-E.1J / E.2A evidence construction remains source-compatible.
    economic_perimeter: str | None = None
    geographic_scope: str | None = None
    time_basis: str | None = None
    rationale: str | None = None

    def __post_init__(self):
        if self.value_numeric is None and self.value_text is None:
            raise ValueError(f"{self.metric_code}: evidence requires numeric or text value.")


@dataclass(frozen=True)
class CalculationRecord:
    metric_code: str
    formula_code: str
    formula_version: str
    formula_expression: str
    input_metric_codes: tuple[str, ...]
    output_value_numeric: float
    unit: str | None = None
    currency: str | None = None


@dataclass
class AssessmentQualityGate:
    methodology_integrity: str = "PASS"
    evidence_quality: str = "PASS"
    scope_consistency: str = "PASS"
    output_quality: str = "PASS"
    management_suitability: str = "PASS"
    warnings: list[str] = field(default_factory=list)
    blocking_issues: list[str] = field(default_factory=list)
    publication_result: PublicationResult = PublicationResult.PUBLISH

    def to_dict(self) -> dict:
        out = asdict(self)
        out["publication_result"] = self.publication_result.value
        return out


@dataclass
class WalletAssessment:
    product: str
    methodology_code: str
    methodology_version: str
    effective_date: str | None = None
    currency: str | None = None
    geographic_scope: str = "Global"
    time_horizon: str = "N/A"
    addressable_notional: float | None = None
    captured_notional: float | None = None
    notional_penetration: float | None = None
    estimated_wallet_revenue: float | None = None
    actual_bank_revenue: float | None = None
    revenue_share_of_wallet: float | None = None
    revenue_wallet_gap: float | None = None
    notional_completeness: CompletenessStatus = CompletenessStatus.PARTIAL
    revenue_wallet_completeness: CompletenessStatus = CompletenessStatus.PARTIAL
    confidence: ConfidenceLevel | None = None
    confidence_explanation: str | None = None
    status: AssessmentStatus = AssessmentStatus.DRAFT
    quality_gate: AssessmentQualityGate | None = None


FORECAST_CAPEX = "FORECAST_CAPEX"
CAPEX_DEBT_FUNDING_PCT = "CAPEX_DEBT_FUNDING_PCT"
BANK_DEBT_SHARE = "BANK_DEBT_SHARE"
RELEVANT_DEBT = "RELEVANT_DEBT"
DEBT_DUE_PCT = "DEBT_DUE_PCT"
BANK_DEBT_SHARE_REFINANCING = "BANK_DEBT_SHARE_REFINANCING"

BANK_CAPEX_NOTIONAL = "BANK_CAPEX_NOTIONAL"
BANK_REFINANCING_NOTIONAL = "BANK_REFINANCING_NOTIONAL"
ADDRESSABLE_LENDING_NOTIONAL = "ADDRESSABLE_LENDING_NOTIONAL"

LENDING_V01_CRITICAL_METRICS = (
    FORECAST_CAPEX,
    CAPEX_DEBT_FUNDING_PCT,
    BANK_DEBT_SHARE,
)


def _stage1e_json(value) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)


def _stage1e_evidence_map(evidence: list[EvidenceItem]) -> dict[str, EvidenceItem]:
    return {item.metric_code: item for item in evidence}


def _stage1e_numeric(ev: dict[str, EvidenceItem], metric: str) -> float | None:
    item = ev.get(metric)
    if item is None or item.value_numeric is None:
        return None
    return float(item.value_numeric)


def _stage1e_derive_confidence(
    evidence: list[EvidenceItem],
    critical_metrics=LENDING_V01_CRITICAL_METRICS,
) -> tuple[ConfidenceLevel | None, str]:
    ev = _stage1e_evidence_map(evidence)
    missing = [m for m in critical_metrics if m not in ev]
    if missing:
        return None, f"Confidence unavailable — missing critical evidence: {', '.join(missing)}."

    levels = [ev[m].confidence for m in critical_metrics]
    if ConfidenceLevel.LOW in levels:
        level = ConfidenceLevel.LOW
    elif ConfidenceLevel.MEDIUM in levels:
        level = ConfidenceLevel.MEDIUM
    else:
        level = ConfidenceLevel.HIGH

    counts = {x: levels.count(x) for x in ConfidenceLevel}
    explanation = (
        f"{level.value.title()} confidence — critical inputs: "
        f"{counts[ConfidenceLevel.HIGH]} high, "
        f"{counts[ConfidenceLevel.MEDIUM]} medium, "
        f"{counts[ConfidenceLevel.LOW]} low."
    )
    return level, explanation


def _stage1e_calculate_lending_wallet_v01(
    evidence: list[EvidenceItem],
    *,
    effective_date: str | None = None,
    currency: str | None = None,
    geographic_scope: str = "Global",
    time_horizon: str = "3Y",
) -> tuple[WalletAssessment, list[CalculationRecord]]:
    """Deterministic Lending Wallet v0.1. Revenue wallet remains NULL."""
    ev = _stage1e_evidence_map(evidence)
    calculations: list[CalculationRecord] = []

    capex = _stage1e_numeric(ev, FORECAST_CAPEX)
    debt_funding = _stage1e_numeric(ev, CAPEX_DEBT_FUNDING_PCT)
    bank_share = _stage1e_numeric(ev, BANK_DEBT_SHARE)

    capex_notional = None
    if capex is not None and debt_funding is not None and bank_share is not None:
        capex_notional = capex * debt_funding * bank_share
        calculations.append(CalculationRecord(
            metric_code=BANK_CAPEX_NOTIONAL,
            formula_code="LENDING_CAPEX_001",
            formula_version="1.0",
            formula_expression="FORECAST_CAPEX * CAPEX_DEBT_FUNDING_PCT * BANK_DEBT_SHARE",
            input_metric_codes=(FORECAST_CAPEX, CAPEX_DEBT_FUNDING_PCT, BANK_DEBT_SHARE),
            output_value_numeric=capex_notional,
            unit="MONEY",
            currency=currency,
        ))

    relevant_debt = _stage1e_numeric(ev, RELEVANT_DEBT)
    debt_due_pct = _stage1e_numeric(ev, DEBT_DUE_PCT)
    refi_bank_share = _stage1e_numeric(ev, BANK_DEBT_SHARE_REFINANCING)
    if refi_bank_share is None:
        refi_bank_share = bank_share

    refi_notional = None
    if relevant_debt is not None and debt_due_pct is not None and refi_bank_share is not None:
        refi_notional = relevant_debt * debt_due_pct * refi_bank_share
        calculations.append(CalculationRecord(
            metric_code=BANK_REFINANCING_NOTIONAL,
            formula_code="LENDING_REFI_001",
            formula_version="1.0",
            formula_expression="RELEVANT_DEBT * DEBT_DUE_PCT * BANK_DEBT_SHARE_REFINANCING",
            input_metric_codes=(
                RELEVANT_DEBT,
                DEBT_DUE_PCT,
                BANK_DEBT_SHARE_REFINANCING
                if BANK_DEBT_SHARE_REFINANCING in ev else BANK_DEBT_SHARE,
            ),
            output_value_numeric=refi_notional,
            unit="MONEY",
            currency=currency,
        ))

    available = [x for x in (capex_notional, refi_notional) if x is not None]
    addressable = sum(available) if available else None
    if addressable is not None:
        calculations.append(CalculationRecord(
            metric_code=ADDRESSABLE_LENDING_NOTIONAL,
            formula_code="LENDING_TOTAL_001",
            formula_version="1.0",
            formula_expression="BANK_CAPEX_NOTIONAL + BANK_REFINANCING_NOTIONAL (available components)",
            input_metric_codes=tuple(
                code for code, value in (
                    (BANK_CAPEX_NOTIONAL, capex_notional),
                    (BANK_REFINANCING_NOTIONAL, refi_notional),
                ) if value is not None
            ),
            output_value_numeric=addressable,
            unit="MONEY",
            currency=currency,
        ))

    confidence, explanation = _stage1e_derive_confidence(evidence)

    # Core Lending v0.1 requires the capex branch. Refinancing remains optional
    # until same-perimeter maturity evidence is available.
    notional_completeness = (
        CompletenessStatus.COMPLETE
        if capex_notional is not None
        else CompletenessStatus.PARTIAL
    )

    return WalletAssessment(
        product="LENDING",
        methodology_code="LENDING_WALLET",
        methodology_version="0.1",
        effective_date=effective_date,
        currency=currency,
        geographic_scope=geographic_scope,
        time_horizon=time_horizon,
        addressable_notional=addressable,
        notional_completeness=notional_completeness,
        revenue_wallet_completeness=CompletenessStatus.PARTIAL,
        confidence=confidence,
        confidence_explanation=explanation,
    ), calculations


def _stage1e_quality_gate(
    assessment: WalletAssessment,
    evidence: list[EvidenceItem],
    *,
    scope_consistent: bool = True,
) -> AssessmentQualityGate:
    ev = _stage1e_evidence_map(evidence)
    gate = AssessmentQualityGate()

    missing = [m for m in LENDING_V01_CRITICAL_METRICS if m not in ev]
    if missing:
        gate.methodology_integrity = "FAIL"
        gate.blocking_issues.append(
            f"Missing critical methodology inputs: {', '.join(missing)}."
        )
    if assessment.addressable_notional is None:
        gate.methodology_integrity = "FAIL"
        gate.blocking_issues.append("Addressable notional could not be calculated.")

    for metric in LENDING_V01_CRITICAL_METRICS:
        item = ev.get(metric)
        if item is None:
            continue
        if not item.source_type or not item.source_name:
            gate.evidence_quality = "FAIL"
            gate.blocking_issues.append(
                f"{metric}: critical evidence has unresolved provenance."
            )
        elif item.confidence == ConfidenceLevel.LOW:
            gate.evidence_quality = "HOLD"
            gate.warnings.append(f"{metric}: critical input is LOW confidence.")

    if not scope_consistent:
        gate.scope_consistency = "FAIL"
        gate.blocking_issues.append(
            "Economic perimeter / geography / period / currency scope is inconsistent."
        )

    if assessment.addressable_notional is not None and assessment.addressable_notional < 0:
        gate.output_quality = "FAIL"
        gate.blocking_issues.append("Addressable notional cannot be negative.")

    if assessment.notional_penetration is not None:
        if assessment.notional_penetration < 0:
            gate.output_quality = "FAIL"
            gate.blocking_issues.append("Notional penetration cannot be negative.")
        elif assessment.notional_penetration > 1:
            gate.output_quality = "HOLD"
            gate.warnings.append(
                "Notional penetration exceeds 100%; verify denominator, period and perimeter."
            )

    if assessment.confidence is None:
        gate.management_suitability = "FAIL"
        gate.blocking_issues.append("Assessment confidence is unavailable.")
    elif assessment.confidence == ConfidenceLevel.LOW:
        gate.management_suitability = "HOLD"
        gate.warnings.append(
            "Overall assessment confidence is LOW; management use requires clarification."
        )

    if gate.blocking_issues:
        gate.publication_result = PublicationResult.REJECT
    elif "HOLD" in {
        gate.evidence_quality,
        gate.output_quality,
        gate.management_suitability,
    }:
        gate.publication_result = PublicationResult.HOLD
    else:
        gate.publication_result = PublicationResult.PUBLISH

    assessment.quality_gate = gate
    return gate


def _db_seed_stage1e_methodologies(conn: _DBConnection):
    """Idempotently register Lending Wallet v0.1 methodology."""
    existing = conn.execute(
        """SELECT * FROM intelligence_methodology
           WHERE methodology_code=? AND version=?""",
        ("LENDING_WALLET", "0.1"),
    ).fetchone()
    if existing is not None:
        return existing

    methodology_id = _db_next_id(
        conn, "intelligence_methodology", "methodology_id", "MTH"
    )
    now = _db_now()
    conn.execute(
        """INSERT INTO intelligence_methodology(
               methodology_id,methodology_code,methodology_name,version,domain,product,
               description,required_inputs_json,optional_inputs_json,outputs_json,
               critical_inputs_json,effective_from,status,created_at,updated_at
           ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            methodology_id,
            "LENDING_WALLET",
            "Lending Wallet v0.1",
            "0.1",
            "WALLET",
            "LENDING",
            "Addressable bank lending notional from capex financing plus optional refinancing.",
            _stage1e_json([FORECAST_CAPEX, CAPEX_DEBT_FUNDING_PCT, BANK_DEBT_SHARE]),
            _stage1e_json([RELEVANT_DEBT, DEBT_DUE_PCT, BANK_DEBT_SHARE_REFINANCING]),
            _stage1e_json([
                BANK_CAPEX_NOTIONAL,
                BANK_REFINANCING_NOTIONAL,
                ADDRESSABLE_LENDING_NOTIONAL,
            ]),
            _stage1e_json(list(LENDING_V01_CRITICAL_METRICS)),
            now,
            "ACTIVE",
            now,
            now,
        ),
    )
    return conn.execute(
        "SELECT * FROM intelligence_methodology WHERE methodology_id=?",
        (methodology_id,),
    ).fetchone()


def _db_stage1e_persist_evidence(
    conn: _DBConnection,
    *,
    relationship_db_id: int,
    review_cycle_db_id: int,
    methodology_db_id: int,
    item: EvidenceItem,
) -> str:
    evidence_id = _db_next_id(
        conn, "intelligence_evidence", "evidence_id", "EVD"
    )
    conn.execute(
        """INSERT INTO intelligence_evidence(
               evidence_id,relationship_id,review_cycle_id,methodology_id,
               metric_code,metric_name,value_numeric,value_text,unit,currency,
               evidence_type,source_type,source_name,source_reference,
               effective_date,as_of_date,confidence,owner,review_date,
               economic_perimeter,geographic_scope,time_basis,rationale,created_at
           ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            evidence_id, relationship_db_id, review_cycle_db_id, methodology_db_id,
            item.metric_code, item.metric_name, item.value_numeric, item.value_text,
            item.unit, item.currency, item.evidence_type.value, item.source_type,
            item.source_name, item.source_reference, item.effective_date,
            item.as_of_date, item.confidence.value, item.owner, item.review_date,
            item.economic_perimeter, item.geographic_scope, item.time_basis,
            item.rationale, _db_now(),
        ),
    )
    return evidence_id


def _db_stage1e_persist_calculation(
    conn: _DBConnection,
    *,
    relationship_db_id: int,
    review_cycle_db_id: int,
    methodology_db_id: int,
    record: CalculationRecord,
    input_evidence_ids: list[str],
) -> str:
    calculation_id = _db_next_id(
        conn, "intelligence_calculation", "calculation_id", "CAL"
    )
    conn.execute(
        """INSERT INTO intelligence_calculation(
               calculation_id,relationship_id,review_cycle_id,methodology_id,
               metric_code,metric_name,formula_code,formula_version,formula_expression,
               input_evidence_ids_json,output_value_numeric,unit,currency,calculated_at
           ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            calculation_id, relationship_db_id, review_cycle_db_id, methodology_db_id,
            record.metric_code, None, record.formula_code, record.formula_version,
            record.formula_expression, _stage1e_json(input_evidence_ids),
            record.output_value_numeric, record.unit, record.currency, _db_now(),
        ),
    )
    return calculation_id


def _db_stage1e_create_lending_assessment(
    company: str,
    evidence: list[EvidenceItem],
    *,
    effective_date: str | None = None,
    currency: str | None = None,
    geographic_scope: str = "Global",
    time_horizon: str = "3Y",
    scope_consistent: bool = True,
    actor: str = "EC-AI",
) -> dict:
    """Create + validate, but never auto-publish, a Lending Wallet v0.1 assessment."""
    assessment, calculations = _stage1e_calculate_lending_wallet_v01(
        evidence,
        effective_date=effective_date,
        currency=currency,
        geographic_scope=geographic_scope,
        time_horizon=time_horizon,
    )
    gate = _stage1e_quality_gate(
        assessment, evidence, scope_consistent=scope_consistent
    )

    with _db_transaction() as conn:
        methodology = _db_seed_stage1e_methodologies(conn)
        cycle = _db_active_review_cycle(conn)
        rel = _db_relationship_row(conn, company)

        evidence_ids = []
        evidence_by_metric = {}
        for item in evidence:
            evidence_id = _db_stage1e_persist_evidence(
                conn,
                relationship_db_id=rel["id"],
                review_cycle_db_id=cycle["id"],
                methodology_db_id=methodology["id"],
                item=item,
            )
            evidence_ids.append(evidence_id)
            evidence_by_metric[item.metric_code] = evidence_id

        calculation_ids = []
        for calc in calculations:
            input_ids = [
                evidence_by_metric[m]
                for m in calc.input_metric_codes
                if m in evidence_by_metric
            ]
            calc_id = _db_stage1e_persist_calculation(
                conn,
                relationship_db_id=rel["id"],
                review_cycle_db_id=cycle["id"],
                methodology_db_id=methodology["id"],
                record=calc,
                input_evidence_ids=input_ids,
            )
            calculation_ids.append(calc_id)

        assessment_id = _db_next_id(
            conn, "wallet_assessment", "assessment_id", "WAL"
        )
        now = _db_now()
        status = (
            AssessmentStatus.VALIDATED.value
            if gate.publication_result != PublicationResult.REJECT
            else AssessmentStatus.DRAFT.value
        )
        validated_at = now if status == AssessmentStatus.VALIDATED.value else None

        conn.execute(
            """INSERT INTO wallet_assessment(
                   assessment_id,relationship_id,review_cycle_id,methodology_id,
                   product,effective_date,currency,geographic_scope,time_horizon,
                   evidence_ids_json,calculation_ids_json,
                   addressable_notional,captured_notional,notional_penetration,
                   estimated_wallet_revenue,actual_bank_revenue,revenue_share_of_wallet,
                   revenue_wallet_gap,notional_completeness,revenue_wallet_completeness,
                   confidence,confidence_explanation,status,publication_result,
                   quality_gate_json,created_at,validated_at
               ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                assessment_id, rel["id"], cycle["id"], methodology["id"],
                assessment.product, assessment.effective_date, assessment.currency,
                assessment.geographic_scope, assessment.time_horizon,
                _stage1e_json(evidence_ids), _stage1e_json(calculation_ids),
                assessment.addressable_notional, assessment.captured_notional,
                assessment.notional_penetration, assessment.estimated_wallet_revenue,
                assessment.actual_bank_revenue, assessment.revenue_share_of_wallet,
                assessment.revenue_wallet_gap, assessment.notional_completeness.value,
                assessment.revenue_wallet_completeness.value,
                assessment.confidence.value if assessment.confidence else None,
                assessment.confidence_explanation, status,
                gate.publication_result.value, _stage1e_json(gate.to_dict()),
                now, validated_at,
            ),
        )

        _db_append_audit(
            conn,
            entity_type="WalletAssessment",
            entity_id=assessment_id,
            relationship_id=rel["id"],
            event_type="WALLET_ASSESSMENT_CREATED",
            actor=actor,
            payload={
                "product": assessment.product,
                "methodology": "LENDING_WALLET 0.1",
                "status": status,
                "publication_result": gate.publication_result.value,
                "confidence": assessment.confidence.value if assessment.confidence else None,
                "addressable_notional": assessment.addressable_notional,
                "currency": assessment.currency,
            },
        )

        if status == AssessmentStatus.VALIDATED.value:
            _db_append_audit(
                conn,
                entity_type="WalletAssessment",
                entity_id=assessment_id,
                relationship_id=rel["id"],
                event_type="WALLET_ASSESSMENT_VALIDATED",
                actor=actor,
                payload={
                    "publication_result": gate.publication_result.value,
                    "warnings": gate.warnings,
                },
            )

    return {
        "assessment_id": assessment_id,
        "relationship": company,
        "review_cycle_id": cycle["review_cycle_id"],
        "methodology": "LENDING_WALLET 0.1",
        "addressable_notional": assessment.addressable_notional,
        "currency": assessment.currency,
        "notional_completeness": assessment.notional_completeness.value,
        "revenue_wallet": assessment.estimated_wallet_revenue,
        "confidence": assessment.confidence.value if assessment.confidence else None,
        "publication_result": gate.publication_result.value,
        "status": status,
        "warnings": gate.warnings,
        "blocking_issues": gate.blocking_issues,
    }


def _db_stage1e_publish_assessment(
    assessment_id: str,
    *,
    actor: str,
) -> dict:
    """Manual publication gate; supersession occurs atomically."""
    with _db_transaction() as conn:
        target_sql = "SELECT * FROM wallet_assessment WHERE assessment_id=?"
        if conn.backend == "postgresql":
            target_sql += " FOR UPDATE"
        row = conn.execute(target_sql, (assessment_id,)).fetchone()
        if row is None:
            raise ValueError(f"Wallet assessment {assessment_id} not found.")
        if row["status"] != AssessmentStatus.VALIDATED.value:
            raise ValueError(
                f"Only VALIDATED assessments can be published; found {row['status']}."
            )
        if row["publication_result"] != PublicationResult.PUBLISH.value:
            raise ValueError(
                f"Assessment publication_result must be PUBLISH; found {row['publication_result']}."
            )
        if bool(row["test_only"]):
            raise ValueError("TEST-only assessments cannot be published to production intelligence.")

        now = _db_now()
        conn.execute(
            """UPDATE wallet_assessment
               SET status='SUPERSEDED',superseded_at=?
               WHERE relationship_id=? AND product=? AND geographic_scope=? AND time_horizon=?
                 AND status='PUBLISHED' AND assessment_id<>?""",
            (
                now, row["relationship_id"], row["product"],
                row["geographic_scope"], row["time_horizon"], assessment_id,
            ),
        )
        conn.execute(
            """UPDATE wallet_assessment
               SET status='PUBLISHED',published_at=?,published_by=?,publication_mode='MANUAL'
               WHERE assessment_id=?""",
            (now, actor, assessment_id),
        )
        _db_append_audit(
            conn,
            entity_type="WalletAssessment",
            entity_id=assessment_id,
            relationship_id=row["relationship_id"],
            event_type="WALLET_ASSESSMENT_PUBLISHED",
            actor=actor,
            payload={"publication_mode": "MANUAL"},
        )

    return _db_stage1e_get_assessment(assessment_id)


def _db_stage1e_get_assessment(assessment_id: str) -> dict | None:
    conn = _db_connect()
    try:
        row = conn.execute(
            """SELECT wa.*, r.name AS relationship_name,
                      im.methodology_code, im.version AS methodology_version
               FROM wallet_assessment wa
               JOIN relationship r ON r.id=wa.relationship_id
               JOIN intelligence_methodology im ON im.id=wa.methodology_id
               WHERE wa.assessment_id=?""",
            (assessment_id,),
        ).fetchone()
        if row is None:
            return None
        return {
            "Assessment ID": row["assessment_id"],
            "Relationship": row["relationship_name"],
            "Product": row["product"],
            "Methodology": f"{row['methodology_code']} {row['methodology_version']}",
            "Addressable Notional": row["addressable_notional"],
            "Currency": row["currency"] or "",
            "Notional Completeness": row["notional_completeness"],
            "Revenue Wallet": row["estimated_wallet_revenue"],
            "Revenue Completeness": row["revenue_wallet_completeness"],
            "Confidence": row["confidence"] or "",
            "Confidence Explanation": row["confidence_explanation"] or "",
            "Status": row["status"],
            "Publication Result": row["publication_result"] or "",
            "Wallet Scope": row["wallet_scope"] or "",
            "Wallet Coverage": row["wallet_coverage"] or "",
            "Capex Component Status": row["capex_component_status"] or "",
            "Refinancing Component Status": row["refinancing_component_status"] or "",
            "Capture Component Status": row["capture_component_status"] or "",
            "Bank Capex Notional": row["bank_capex_notional"],
            "Bank Refinancing Notional": row["bank_refinancing_notional"],
            "Raw Wallet Gap": row["raw_wallet_gap"],
            "Positive Wallet Gap": row["positive_wallet_gap"],
            "Capture Comparability": row["capture_comparability_status"] or "",
            "Liquidity Component Status": row["liquidity_component_status"] or "",
            "Relevant Cash Pool": row["relevant_cash_pool"],
            "Forecast Bankable Liquidity Share": row["forecast_bankable_liquidity_share"],
            "Liquidity Time Basis": row["liquidity_time_basis"] or "",
            "Test Only": bool(row["test_only"]),
            "Economic Interpretation": row["economic_interpretation_json"] or "{}",
            "Created": row["created_at"],
            "Validated": row["validated_at"] or "",
            "Published": row["published_at"] or "",
            "Published By": row["published_by"] or "",
        }
    finally:
        conn.close()


def _db_stage1e_current_assessment(
    company: str,
    *,
    product: str = "LENDING",
    geographic_scope: str = "Global",
    time_horizon: str = "3Y",
) -> dict | None:
    conn = _db_connect()
    try:
        rel = _db_relationship_row(conn, company)
        row = conn.execute(
            """SELECT assessment_id FROM wallet_assessment
               WHERE relationship_id=? AND product=? AND geographic_scope=? AND time_horizon=?
                 AND status='PUBLISHED'
               ORDER BY id DESC LIMIT 1""",
            (rel["id"], product, geographic_scope, time_horizon),
        ).fetchone()
        if row is None:
            return None
        assessment_id = row["assessment_id"]
    finally:
        conn.close()
    return _db_stage1e_get_assessment(assessment_id)


def _stage1e_toyota_test_evidence() -> list[EvidenceItem]:
    """Controlled TEST fixture only. The 25% capex-debt assumption is not production truth."""
    return [
        EvidenceItem(
            metric_code=FORECAST_CAPEX,
            metric_name="Forecast Capex",
            value_numeric=2_300_000_000_000,
            currency="JPY",
            evidence_type=EvidenceType.FACT,
            source_type="COMPANY_DISCLOSURE",
            source_name="Toyota FY2027 guidance — test fixture",
            confidence=ConfidenceLevel.HIGH,
        ),
        EvidenceItem(
            metric_code=CAPEX_DEBT_FUNDING_PCT,
            metric_name="Capex Debt Funding %",
            value_numeric=0.25,
            unit="PERCENT",
            evidence_type=EvidenceType.ASSUMPTION,
            source_type="INDUSTRY_BENCHMARK",
            source_name="Governed TEST benchmark — not production assumption",
            confidence=ConfidenceLevel.MEDIUM,
        ),
        EvidenceItem(
            metric_code=BANK_DEBT_SHARE,
            metric_name="Bank Debt Share",
            value_numeric=0.657,
            unit="PERCENT",
            evidence_type=EvidenceType.DERIVED_FACT,
            source_type="MODEL_DERIVATION",
            source_name="Toyota parent funding-mix proxy — test fixture",
            confidence=ConfidenceLevel.MEDIUM,
        ),
    ]


def _db_stage1e_run_toyota_test(*, actor: str = "Founder Test") -> dict:
    """Explicit test helper. Never called automatically on app startup."""
    return _db_stage1e_create_lending_assessment(
        "Toyota",
        _stage1e_toyota_test_evidence(),
        effective_date="FY2027",
        currency="JPY",
        geographic_scope="Global",
        time_horizon="3Y",
        scope_consistent=True,
        actor=actor,
    )





# STAGE 1-E.2A.6 — STRUCTURAL LENDING WALLET v1.0 / RED-TEAMED ENGINE
# =============================================================================
# Additive candidate logic only. Stage 1-E.1J persistence and any existing
# PUBLISHED assessments remain untouched. This engine has no database writes.
#
# Governing contract:
#   Facts -> Evidence + Assumptions -> deterministic wallet calculation
#   -> quality gate -> eligible intelligence.
# Wallet gap is evidence, not a lending recommendation.
# NULL means unknown / not assessed; zero means known zero.

class StructuralComponentStatus(str, Enum):
    COMPLETE = "COMPLETE"
    PARTIAL = "PARTIAL"
    NOT_ASSESSED = "NOT_ASSESSED"
    INVALID = "INVALID"


class StructuralWalletCoverage(str, Enum):
    CAPEX_ONLY = "CAPEX_ONLY"
    REFINANCING_ONLY = "REFINANCING_ONLY"
    CAPEX_AND_REFINANCING = "CAPEX_AND_REFINANCING"
    NOT_ASSESSED = "NOT_ASSESSED"


class CaptureComparabilityStatus(str, Enum):
    COMPARABLE = "COMPARABLE"
    NOT_COMPARABLE = "NOT_COMPARABLE"
    NOT_ASSESSED = "NOT_ASSESSED"


@dataclass(frozen=True)
class StructuralLendingComponent:
    """One structural lending need.

    CAPEX semantics:
        base_amount = forecast capex
        funding_rate = forecast capex debt-funding %
        bank_share = forecast bank share of capex debt funding

    REFINANCING semantics:
        base_amount = relevant principal maturing in the assessment horizon
        funding_rate = forecast external refinance rate
        bank_share = forecast bank share of refinancing
    """
    base_amount: float | None = None
    funding_rate: float | None = None
    bank_share: float | None = None
    economic_perimeter: str | None = None
    time_horizon: str | None = None
    currency: str | None = None
    evidence_ids: tuple[str, ...] = ()
    estimation_method: str | None = None
    rationale: str | None = None
    confidence: str = "MEDIUM"
    financing_need_ids: tuple[str, ...] = ()
    assessed: bool = True


@dataclass(frozen=True)
class StructuralLendingCapture:
    """Our bank's economically comparable position.

    comparable_commitment should represent final committed / retained notional
    matched to the wallet denominator. Funded and pipeline amounts are supporting
    facts and do not replace comparable commitment for primary penetration.
    """
    comparable_commitment: float | None = None
    funded_notional: float | None = None
    pipeline_notional: float | None = None
    comparability_status: CaptureComparabilityStatus = CaptureComparabilityStatus.NOT_ASSESSED
    comparability_reason: str | None = None
    evidence_ids: tuple[str, ...] = ()
    verified_zero: bool = False


@dataclass(frozen=True)
class StructuralLendingAssessmentInput:
    capex: StructuralLendingComponent | None = None
    refinancing: StructuralLendingComponent | None = None
    capture: StructuralLendingCapture | None = None
    methodology_code: str = "STRUCTURAL_LENDING"
    methodology_version: str = "1.0"
    wallet_scope: str = "STRUCTURAL_LENDING"
    test_only: bool = False


def _stage1e2_finite_number(value) -> bool:
    try:
        return value is not None and math.isfinite(float(value))
    except Exception:
        return False


def _stage1e2_component_result(
    name: str,
    component: StructuralLendingComponent | None,
) -> dict:
    """Validate and calculate one component without inferring missing facts."""
    result = {
        "component": name,
        "status": StructuralComponentStatus.NOT_ASSESSED.value,
        "notional": None,
        "warnings": [],
        "blocking_issues": [],
        "scope": None,
        "financing_need_ids": [],
    }

    if component is None or not component.assessed:
        return result

    values = (component.base_amount, component.funding_rate, component.bank_share)
    if any(v is None for v in values):
        result["status"] = StructuralComponentStatus.PARTIAL.value
        result["warnings"].append(f"{name}_MISSING_INPUT")
        return result

    if not all(_stage1e2_finite_number(v) for v in values):
        result["status"] = StructuralComponentStatus.INVALID.value
        result["blocking_issues"].append(f"{name}_NON_FINITE_VALUE")
        return result

    base_amount = float(component.base_amount)
    funding_rate = float(component.funding_rate)
    bank_share = float(component.bank_share)

    if base_amount < 0:
        result["status"] = StructuralComponentStatus.INVALID.value
        result["blocking_issues"].append(f"{name}_NEGATIVE_BASE_AMOUNT")
        return result
    if not 0 <= funding_rate <= 1:
        result["status"] = StructuralComponentStatus.INVALID.value
        result["blocking_issues"].append(f"{name}_FUNDING_RATE_OUT_OF_RANGE")
        return result
    if not 0 <= bank_share <= 1:
        result["status"] = StructuralComponentStatus.INVALID.value
        result["blocking_issues"].append(f"{name}_BANK_SHARE_OUT_OF_RANGE")
        return result

    scope = (
        (component.economic_perimeter or "").strip(),
        (component.time_horizon or "").strip(),
        (component.currency or "").strip().upper(),
    )
    result["scope"] = scope

    if not all(scope):
        result["status"] = StructuralComponentStatus.PARTIAL.value
        result["warnings"].append(f"{name}_MISSING_SCOPE")
        return result

    # Material inputs require lineage and an explicit method/rationale.
    if not component.evidence_ids:
        result["status"] = StructuralComponentStatus.PARTIAL.value
        result["warnings"].append(f"{name}_MISSING_PROVENANCE")
        return result
    if not (component.estimation_method or "").strip():
        result["status"] = StructuralComponentStatus.PARTIAL.value
        result["warnings"].append(f"{name}_MISSING_ESTIMATION_METHOD")
        return result
    if not (component.rationale or "").strip():
        result["status"] = StructuralComponentStatus.PARTIAL.value
        result["warnings"].append(f"{name}_MISSING_RATIONALE")
        return result

    confidence = str(component.confidence or "").upper()
    if confidence not in {"HIGH", "MEDIUM", "LOW"}:
        result["status"] = StructuralComponentStatus.INVALID.value
        result["blocking_issues"].append(f"{name}_INVALID_CONFIDENCE")
        return result

    if confidence == "LOW":
        result["warnings"].append(f"{name}_LOW_CONFIDENCE")

    result["status"] = StructuralComponentStatus.COMPLETE.value
    result["notional"] = base_amount * funding_rate * bank_share
    result["financing_need_ids"] = list(component.financing_need_ids)
    return result


def _stage1e2_capture_result(
    capture: StructuralLendingCapture | None,
    addressable_notional: float | None,
) -> dict:
    result = {
        "status": StructuralComponentStatus.NOT_ASSESSED.value,
        "comparability_status": CaptureComparabilityStatus.NOT_ASSESSED.value,
        "comparable_commitment": None,
        "funded_notional": None,
        "pipeline_notional": None,
        "penetration": None,
        "raw_wallet_gap": None,
        "positive_wallet_gap": None,
        "warnings": [],
        "blocking_issues": [],
    }
    if capture is None:
        return result

    result["comparability_status"] = capture.comparability_status.value
    result["funded_notional"] = (
        float(capture.funded_notional)
        if _stage1e2_finite_number(capture.funded_notional) else None
    )
    result["pipeline_notional"] = (
        float(capture.pipeline_notional)
        if _stage1e2_finite_number(capture.pipeline_notional) else None
    )

    for field_name, raw in (
        ("FUNDED_NOTIONAL", capture.funded_notional),
        ("PIPELINE_NOTIONAL", capture.pipeline_notional),
        ("COMPARABLE_COMMITMENT", capture.comparable_commitment),
    ):
        if raw is not None:
            if not _stage1e2_finite_number(raw) or float(raw) < 0:
                result["status"] = StructuralComponentStatus.INVALID.value
                result["blocking_issues"].append(f"CAPTURE_{field_name}_INVALID")
                return result

    if capture.comparability_status == CaptureComparabilityStatus.NOT_ASSESSED:
        return result

    if capture.comparability_status == CaptureComparabilityStatus.NOT_COMPARABLE:
        result["status"] = StructuralComponentStatus.COMPLETE.value
        if not (capture.comparability_reason or "").strip():
            result["warnings"].append("CAPTURE_NOT_COMPARABLE_REASON_MISSING")
        else:
            result["warnings"].append("CAPTURE_NOT_COMPARABLE")
        return result

    # COMPARABLE
    if not capture.evidence_ids:
        result["status"] = StructuralComponentStatus.PARTIAL.value
        result["warnings"].append("CAPTURE_MISSING_PROVENANCE")
        return result

    if not (capture.comparability_reason or "").strip():
        result["status"] = StructuralComponentStatus.PARTIAL.value
        result["warnings"].append("CAPTURE_COMPARABILITY_REASON_MISSING")
        return result

    commitment = capture.comparable_commitment
    if commitment is None and capture.verified_zero:
        commitment = 0.0

    if commitment is None:
        result["status"] = StructuralComponentStatus.PARTIAL.value
        result["warnings"].append("CAPTURE_COMPARABLE_COMMITMENT_UNKNOWN")
        return result

    result["status"] = StructuralComponentStatus.COMPLETE.value
    result["comparable_commitment"] = float(commitment)

    if addressable_notional is not None:
        raw_gap = float(addressable_notional) - float(commitment)
        result["raw_wallet_gap"] = raw_gap
        result["positive_wallet_gap"] = max(0.0, raw_gap)
        if addressable_notional > 0:
            result["penetration"] = float(commitment) / float(addressable_notional)
            if result["penetration"] > 1:
                result["warnings"].append("CAPTURE_EXCEEDS_ESTIMATED_WALLET")
        elif addressable_notional == 0 and float(commitment) > 0:
            result["warnings"].append("CAPTURE_WITH_ZERO_ESTIMATED_WALLET")

    return result


def _stage1e2_evaluate_structural_lending(
    assessment: StructuralLendingAssessmentInput,
) -> dict:
    """Deterministic Stage 1-E.2A structural lending assessment.

    No persistence and no management recommendation are produced here.
    """
    capex = _stage1e2_component_result("CAPEX", assessment.capex)
    refi = _stage1e2_component_result("REFINANCING", assessment.refinancing)

    component_results = {"CAPEX": capex, "REFINANCING": refi}
    warnings = list(capex["warnings"]) + list(refi["warnings"])
    blockers = list(capex["blocking_issues"]) + list(refi["blocking_issues"])

    complete = [
        name for name, result in component_results.items()
        if result["status"] == StructuralComponentStatus.COMPLETE.value
    ]
    partial = [
        name for name, result in component_results.items()
        if result["status"] == StructuralComponentStatus.PARTIAL.value
    ]
    invalid = [
        name for name, result in component_results.items()
        if result["status"] == StructuralComponentStatus.INVALID.value
    ]

    if complete == ["CAPEX"]:
        coverage = StructuralWalletCoverage.CAPEX_ONLY.value
    elif complete == ["REFINANCING"]:
        coverage = StructuralWalletCoverage.REFINANCING_ONLY.value
    elif set(complete) == {"CAPEX", "REFINANCING"}:
        coverage = StructuralWalletCoverage.CAPEX_AND_REFINANCING.value
    else:
        coverage = StructuralWalletCoverage.NOT_ASSESSED.value

    addressable = (
        sum(float(component_results[name]["notional"]) for name in complete)
        if complete else None
    )

    # Both complete components must share the same economic perimeter, horizon
    # and currency before they can be summed without qualification.
    if len(complete) == 2 and capex["scope"] != refi["scope"]:
        warnings.append("SCOPE_MISMATCH")

    # Financing need IDs are explicit anti-double-counting keys. We do not
    # silently net overlapping needs; the assessment is held for analyst review.
    if len(complete) == 2:
        capex_needs = set(capex["financing_need_ids"])
        refi_needs = set(refi["financing_need_ids"])
        if capex_needs.intersection(refi_needs):
            warnings.append("POTENTIAL_DOUBLE_COUNT")

    if partial:
        warnings.append("INCOMPLETE_ASSESSED_COMPONENT")

    if invalid:
        blockers.append("INVALID_STRUCTURAL_LENDING_COMPONENT")

    capture = _stage1e2_capture_result(assessment.capture, addressable)
    warnings.extend(capture["warnings"])
    blockers.extend(capture["blocking_issues"])

    if assessment.methodology_code != "STRUCTURAL_LENDING":
        blockers.append("UNSUPPORTED_METHODOLOGY_CODE")
    if assessment.methodology_version != "1.0":
        blockers.append("UNSUPPORTED_METHODOLOGY_VERSION")
    if assessment.wallet_scope != "STRUCTURAL_LENDING":
        blockers.append("UNSUPPORTED_WALLET_SCOPE")
    if not complete:
        blockers.append("NO_COMPLETE_STRUCTURAL_LENDING_COMPONENT")
    if assessment.test_only:
        warnings.append("TEST_ONLY_NOT_FOR_PRODUCTION")

    warnings = sorted(set(warnings))
    blockers = sorted(set(blockers))

    hold_codes = {
        "SCOPE_MISMATCH",
        "POTENTIAL_DOUBLE_COUNT",
        "INCOMPLETE_ASSESSED_COMPONENT",
        "CAPEX_LOW_CONFIDENCE",
        "REFINANCING_LOW_CONFIDENCE",
        "TEST_ONLY_NOT_FOR_PRODUCTION",
    }

    if blockers:
        publication_result = PublicationResult.REJECT.value
    elif any(code in hold_codes for code in warnings):
        publication_result = PublicationResult.HOLD.value
    else:
        publication_result = PublicationResult.PUBLISH.value

    production_publication_allowed = (
        publication_result == PublicationResult.PUBLISH.value
        and not assessment.test_only
    )

    # Freeze the economic interpretation as part of the returned contract. A
    # later persistence step should store this snapshot rather than regenerate
    # history from mutable current assumptions.
    snapshot = {
        "methodology_code": assessment.methodology_code,
        "methodology_version": assessment.methodology_version,
        "wallet_scope": assessment.wallet_scope,
        "wallet_coverage": coverage,
        "component_status": {
            "CAPEX": capex["status"],
            "REFINANCING": refi["status"],
            "CAPTURE": capture["status"],
        },
        "component_notional": {
            "CAPEX": capex["notional"],
            "REFINANCING": refi["notional"],
        },
        "addressable_structural_lending_notional": addressable,
        "comparable_capture_notional": capture["comparable_commitment"],
        "notional_penetration": capture["penetration"],
        "raw_wallet_gap": capture["raw_wallet_gap"],
        "positive_wallet_gap": capture["positive_wallet_gap"],
        "capture_comparability_status": capture["comparability_status"],
        "warnings": warnings,
        "blocking_issues": blockers,
        "publication_result": publication_result,
        "production_publication_allowed": production_publication_allowed,
    }
    return snapshot


def _stage1e2_toyota_dry_run() -> dict:
    """Controlled dry run only; never writes or publishes.

    The 25% capex debt-funding assumption remains TEST-only and the 65.7% bank
    share remains a historical parent funding-mix proxy, not a Toyota forecast.
    """
    capex = StructuralLendingComponent(
        base_amount=2_300_000_000_000,
        funding_rate=0.25,
        bank_share=0.657,
        economic_perimeter="TOYOTA_PARENT",
        time_horizon="3Y",
        currency="JPY",
        evidence_ids=("TEST-FORECAST-CAPEX", "TEST-DEBT-FUNDING", "TEST-BANK-SHARE"),
        estimation_method="Governed test assumption + historical parent funding-mix proxy",
        rationale="Validate deterministic Stage 1-E.2A mechanics only; not production truth.",
        confidence="MEDIUM",
        financing_need_ids=("TOYOTA-FY2027-CAPEX",),
        assessed=True,
    )
    return _stage1e2_evaluate_structural_lending(
        StructuralLendingAssessmentInput(
            capex=capex,
            refinancing=None,
            capture=None,
            test_only=True,
        )
    )

# END STAGE 1-E.2A.6 — STRUCTURAL LENDING WALLET v1.0

# =============================================================================
# STAGE 1-E.2A.7 — STRUCTURAL LENDING v1.0 PERSISTENCE INTEGRATION
# =============================================================================
# This layer reuses the Stage 1-E.1J evidence / calculation / assessment tables.
# It is additive: LENDING_WALLET 0.1 and existing WAL-* rows remain historical.
# Test-only assessments can be VALIDATED but are never eligible for publication.

FORECAST_CAPEX_DEBT_FUNDING_PCT = "FORECAST_CAPEX_DEBT_FUNDING_PCT"
FORECAST_BANK_CAPEX_SHARE = "FORECAST_BANK_CAPEX_SHARE"
RELEVANT_PRINCIPAL_MATURING = "RELEVANT_PRINCIPAL_MATURING"
FORECAST_EXTERNAL_REFINANCE_RATE = "FORECAST_EXTERNAL_REFINANCE_RATE"
FORECAST_BANK_REFINANCE_SHARE = "FORECAST_BANK_REFINANCE_SHARE"
OUR_BANK_COMPARABLE_COMMITMENT = "OUR_BANK_COMPARABLE_COMMITMENT"
OUR_BANK_FUNDED_NOTIONAL = "OUR_BANK_FUNDED_NOTIONAL"
OUR_BANK_PIPELINE_NOTIONAL = "OUR_BANK_PIPELINE_NOTIONAL"

STRUCTURAL_BANK_CAPEX_NOTIONAL = "STRUCTURAL_BANK_CAPEX_NOTIONAL"
STRUCTURAL_BANK_REFINANCING_NOTIONAL = "STRUCTURAL_BANK_REFINANCING_NOTIONAL"
STRUCTURAL_LENDING_ADDRESSABLE_NOTIONAL = "STRUCTURAL_LENDING_ADDRESSABLE_NOTIONAL"
STRUCTURAL_LENDING_PENETRATION = "STRUCTURAL_LENDING_PENETRATION"
STRUCTURAL_LENDING_RAW_GAP = "STRUCTURAL_LENDING_RAW_GAP"
STRUCTURAL_LENDING_POSITIVE_GAP = "STRUCTURAL_LENDING_POSITIVE_GAP"


def _db_seed_stage1e2_methodology(conn: _DBConnection):
    """Idempotently register Structural Lending v1.0 alongside legacy v0.1."""
    existing = conn.execute(
        """SELECT * FROM intelligence_methodology
           WHERE methodology_code=? AND version=?""",
        ("STRUCTURAL_LENDING", "1.0"),
    ).fetchone()
    if existing is not None:
        return existing

    methodology_id = _db_next_id(
        conn, "intelligence_methodology", "methodology_id", "MTH"
    )
    now = _db_now()
    conn.execute(
        """INSERT INTO intelligence_methodology(
               methodology_id,methodology_code,methodology_name,version,domain,product,
               description,required_inputs_json,optional_inputs_json,outputs_json,
               critical_inputs_json,effective_from,status,created_at,updated_at
           ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            methodology_id,
            "STRUCTURAL_LENDING",
            "Structural Lending Wallet v1.0",
            "1.0",
            "WALLET",
            "LENDING",
            "Bank-addressable structural lending from assessed capex financing and/or refinancing, with explicit coverage and capture comparability.",
            _stage1e_json([]),
            _stage1e_json([
                FORECAST_CAPEX,
                FORECAST_CAPEX_DEBT_FUNDING_PCT,
                FORECAST_BANK_CAPEX_SHARE,
                RELEVANT_PRINCIPAL_MATURING,
                FORECAST_EXTERNAL_REFINANCE_RATE,
                FORECAST_BANK_REFINANCE_SHARE,
                OUR_BANK_COMPARABLE_COMMITMENT,
                OUR_BANK_FUNDED_NOTIONAL,
                OUR_BANK_PIPELINE_NOTIONAL,
            ]),
            _stage1e_json([
                STRUCTURAL_BANK_CAPEX_NOTIONAL,
                STRUCTURAL_BANK_REFINANCING_NOTIONAL,
                STRUCTURAL_LENDING_ADDRESSABLE_NOTIONAL,
                STRUCTURAL_LENDING_PENETRATION,
                STRUCTURAL_LENDING_RAW_GAP,
                STRUCTURAL_LENDING_POSITIVE_GAP,
            ]),
            _stage1e_json(["AT_LEAST_ONE_COMPLETE_STRUCTURAL_COMPONENT"]),
            now,
            "ACTIVE",
            now,
            now,
        ),
    )
    return conn.execute(
        "SELECT * FROM intelligence_methodology WHERE methodology_id=?",
        (methodology_id,),
    ).fetchone()


def _stage1e2_overall_confidence(assessment_input: StructuralLendingAssessmentInput, snapshot: dict) -> tuple[str | None, str]:
    levels = []
    if snapshot["component_status"]["CAPEX"] == StructuralComponentStatus.COMPLETE.value and assessment_input.capex:
        levels.append(str(assessment_input.capex.confidence).upper())
    if snapshot["component_status"]["REFINANCING"] == StructuralComponentStatus.COMPLETE.value and assessment_input.refinancing:
        levels.append(str(assessment_input.refinancing.confidence).upper())
    if not levels:
        return None, "Confidence unavailable — no complete structural lending component."
    if "LOW" in levels:
        result = "LOW"
    elif "MEDIUM" in levels:
        result = "MEDIUM"
    else:
        result = "HIGH"
    return result, f"{result.title()} confidence across {len(levels)} complete structural lending component(s)."


def _stage1e2_required_metrics_for_snapshot(snapshot: dict) -> set[str]:
    required = set()
    if snapshot["component_status"]["CAPEX"] == StructuralComponentStatus.COMPLETE.value:
        required.update({FORECAST_CAPEX, FORECAST_CAPEX_DEBT_FUNDING_PCT, FORECAST_BANK_CAPEX_SHARE})
    if snapshot["component_status"]["REFINANCING"] == StructuralComponentStatus.COMPLETE.value:
        required.update({RELEVANT_PRINCIPAL_MATURING, FORECAST_EXTERNAL_REFINANCE_RATE, FORECAST_BANK_REFINANCE_SHARE})
    if (
        snapshot["component_status"]["CAPTURE"] == StructuralComponentStatus.COMPLETE.value
        and snapshot["capture_comparability_status"] == CaptureComparabilityStatus.COMPARABLE.value
    ):
        required.add(OUR_BANK_COMPARABLE_COMMITMENT)
    return required


def _stage1e2_build_calculation_records(
    assessment_input: StructuralLendingAssessmentInput,
    snapshot: dict,
    *,
    currency: str | None,
) -> list[CalculationRecord]:
    records = []
    capex_value = snapshot["component_notional"]["CAPEX"]
    refi_value = snapshot["component_notional"]["REFINANCING"]

    if capex_value is not None:
        records.append(CalculationRecord(
            metric_code=STRUCTURAL_BANK_CAPEX_NOTIONAL,
            formula_code="STRUCTURAL_LENDING_CAPEX_001",
            formula_version="1.0",
            formula_expression="FORECAST_CAPEX * FORECAST_CAPEX_DEBT_FUNDING_PCT * FORECAST_BANK_CAPEX_SHARE",
            input_metric_codes=(FORECAST_CAPEX, FORECAST_CAPEX_DEBT_FUNDING_PCT, FORECAST_BANK_CAPEX_SHARE),
            output_value_numeric=float(capex_value),
            unit="MONEY",
            currency=currency,
        ))

    if refi_value is not None:
        records.append(CalculationRecord(
            metric_code=STRUCTURAL_BANK_REFINANCING_NOTIONAL,
            formula_code="STRUCTURAL_LENDING_REFI_001",
            formula_version="1.0",
            formula_expression="RELEVANT_PRINCIPAL_MATURING * FORECAST_EXTERNAL_REFINANCE_RATE * FORECAST_BANK_REFINANCE_SHARE",
            input_metric_codes=(RELEVANT_PRINCIPAL_MATURING, FORECAST_EXTERNAL_REFINANCE_RATE, FORECAST_BANK_REFINANCE_SHARE),
            output_value_numeric=float(refi_value),
            unit="MONEY",
            currency=currency,
        ))

    if snapshot["addressable_structural_lending_notional"] is not None:
        total_inputs = []
        if capex_value is not None:
            total_inputs += [FORECAST_CAPEX, FORECAST_CAPEX_DEBT_FUNDING_PCT, FORECAST_BANK_CAPEX_SHARE]
        if refi_value is not None:
            total_inputs += [RELEVANT_PRINCIPAL_MATURING, FORECAST_EXTERNAL_REFINANCE_RATE, FORECAST_BANK_REFINANCE_SHARE]
        records.append(CalculationRecord(
            metric_code=STRUCTURAL_LENDING_ADDRESSABLE_NOTIONAL,
            formula_code="STRUCTURAL_LENDING_TOTAL_001",
            formula_version="1.0",
            formula_expression="SUM(complete assessed structural lending components)",
            input_metric_codes=tuple(total_inputs),
            output_value_numeric=float(snapshot["addressable_structural_lending_notional"]),
            unit="MONEY",
            currency=currency,
        ))

    if snapshot["notional_penetration"] is not None:
        records.append(CalculationRecord(
            metric_code=STRUCTURAL_LENDING_PENETRATION,
            formula_code="STRUCTURAL_LENDING_CAPTURE_001",
            formula_version="1.0",
            formula_expression="OUR_BANK_COMPARABLE_COMMITMENT / STRUCTURAL_LENDING_ADDRESSABLE_NOTIONAL",
            input_metric_codes=(OUR_BANK_COMPARABLE_COMMITMENT,),
            output_value_numeric=float(snapshot["notional_penetration"]),
            unit="RATIO",
            currency=None,
        ))
    if snapshot["raw_wallet_gap"] is not None:
        records.append(CalculationRecord(
            metric_code=STRUCTURAL_LENDING_RAW_GAP,
            formula_code="STRUCTURAL_LENDING_GAP_001",
            formula_version="1.0",
            formula_expression="STRUCTURAL_LENDING_ADDRESSABLE_NOTIONAL - OUR_BANK_COMPARABLE_COMMITMENT",
            input_metric_codes=(OUR_BANK_COMPARABLE_COMMITMENT,),
            output_value_numeric=float(snapshot["raw_wallet_gap"]),
            unit="MONEY",
            currency=currency,
        ))
    if snapshot["positive_wallet_gap"] is not None:
        records.append(CalculationRecord(
            metric_code=STRUCTURAL_LENDING_POSITIVE_GAP,
            formula_code="STRUCTURAL_LENDING_GAP_002",
            formula_version="1.0",
            formula_expression="MAX(0, STRUCTURAL_LENDING_RAW_GAP)",
            input_metric_codes=(OUR_BANK_COMPARABLE_COMMITMENT,),
            output_value_numeric=float(snapshot["positive_wallet_gap"]),
            unit="MONEY",
            currency=currency,
        ))
    return records


def _db_stage1e2_create_structural_assessment(
    company: str,
    assessment_input: StructuralLendingAssessmentInput,
    evidence: list[EvidenceItem],
    *,
    effective_date: str | None = None,
    currency: str | None = None,
    geographic_scope: str = "Global",
    time_horizon: str = "3Y",
    actor: str = "EC-AI",
) -> dict:
    """Persist a frozen Structural Lending v1.0 assessment without auto-publication."""
    snapshot = _stage1e2_evaluate_structural_lending(assessment_input)
    evidence_map = _stage1e_evidence_map(evidence)
    required_metrics = _stage1e2_required_metrics_for_snapshot(snapshot)
    missing_evidence = sorted(m for m in required_metrics if m not in evidence_map)
    if missing_evidence:
        raise ValueError(
            "Structural Lending persistence refused — complete components lack persisted evidence inputs: "
            + ", ".join(missing_evidence)
        )

    confidence, confidence_explanation = _stage1e2_overall_confidence(assessment_input, snapshot)
    calculations = _stage1e2_build_calculation_records(
        assessment_input, snapshot, currency=currency
    )

    with _db_transaction() as conn:
        methodology = _db_seed_stage1e2_methodology(conn)
        cycle = _db_active_review_cycle(conn)
        rel = _db_relationship_row(conn, company)

        evidence_ids = []
        evidence_by_metric = {}
        for item in evidence:
            evidence_id = _db_stage1e_persist_evidence(
                conn,
                relationship_db_id=rel["id"],
                review_cycle_db_id=cycle["id"],
                methodology_db_id=methodology["id"],
                item=item,
            )
            evidence_ids.append(evidence_id)
            evidence_by_metric[item.metric_code] = evidence_id

        calculation_ids = []
        for calc in calculations:
            input_ids = [
                evidence_by_metric[m]
                for m in calc.input_metric_codes
                if m in evidence_by_metric
            ]
            calc_id = _db_stage1e_persist_calculation(
                conn,
                relationship_db_id=rel["id"],
                review_cycle_db_id=cycle["id"],
                methodology_db_id=methodology["id"],
                record=calc,
                input_evidence_ids=input_ids,
            )
            calculation_ids.append(calc_id)

        # Freeze real persisted lineage in the economic snapshot.
        frozen_snapshot = dict(snapshot)
        frozen_snapshot["evidence_ids"] = list(evidence_ids)
        frozen_snapshot["calculation_ids"] = list(calculation_ids)
        frozen_snapshot["effective_date"] = effective_date
        frozen_snapshot["currency"] = currency
        frozen_snapshot["geographic_scope"] = geographic_scope
        frozen_snapshot["time_horizon"] = time_horizon
        frozen_snapshot["confidence"] = confidence
        frozen_snapshot["confidence_explanation"] = confidence_explanation

        assessment_id = _db_next_id(
            conn, "wallet_assessment", "assessment_id", "WAL"
        )
        now = _db_now()
        status = (
            AssessmentStatus.DRAFT.value
            if snapshot["publication_result"] == PublicationResult.REJECT.value
            else AssessmentStatus.VALIDATED.value
        )
        validated_at = now if status == AssessmentStatus.VALIDATED.value else None
        notional_completeness = (
            CompletenessStatus.COMPLETE.value
            if snapshot["wallet_coverage"] == StructuralWalletCoverage.CAPEX_AND_REFINANCING.value
            else CompletenessStatus.PARTIAL.value
        )
        quality_gate = {
            "methodology": "STRUCTURAL_LENDING 1.0",
            "wallet_scope": snapshot["wallet_scope"],
            "wallet_coverage": snapshot["wallet_coverage"],
            "warnings": snapshot["warnings"],
            "blocking_issues": snapshot["blocking_issues"],
            "publication_result": snapshot["publication_result"],
            "production_publication_allowed": snapshot["production_publication_allowed"],
            "test_only": bool(assessment_input.test_only),
        }

        conn.execute(
            """INSERT INTO wallet_assessment(
                   assessment_id,relationship_id,review_cycle_id,methodology_id,
                   product,effective_date,currency,geographic_scope,time_horizon,
                   evidence_ids_json,calculation_ids_json,
                   addressable_notional,captured_notional,notional_penetration,
                   estimated_wallet_revenue,actual_bank_revenue,revenue_share_of_wallet,
                   revenue_wallet_gap,notional_completeness,revenue_wallet_completeness,
                   confidence,confidence_explanation,status,publication_result,
                   quality_gate_json,wallet_scope,wallet_coverage,
                   capex_component_status,refinancing_component_status,capture_component_status,
                   bank_capex_notional,bank_refinancing_notional,raw_wallet_gap,positive_wallet_gap,
                   capture_comparability_status,test_only,economic_interpretation_json,
                   created_at,validated_at
               ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                assessment_id, rel["id"], cycle["id"], methodology["id"],
                "LENDING", effective_date, currency, geographic_scope, time_horizon,
                _stage1e_json(evidence_ids), _stage1e_json(calculation_ids),
                snapshot["addressable_structural_lending_notional"],
                snapshot["comparable_capture_notional"], snapshot["notional_penetration"],
                None, None, None, None,
                notional_completeness, CompletenessStatus.PARTIAL.value,
                confidence, confidence_explanation, status, snapshot["publication_result"],
                _stage1e_json(quality_gate), snapshot["wallet_scope"], snapshot["wallet_coverage"],
                snapshot["component_status"]["CAPEX"], snapshot["component_status"]["REFINANCING"],
                snapshot["component_status"]["CAPTURE"], snapshot["component_notional"]["CAPEX"],
                snapshot["component_notional"]["REFINANCING"], snapshot["raw_wallet_gap"],
                snapshot["positive_wallet_gap"], snapshot["capture_comparability_status"],
                1 if assessment_input.test_only else 0, _stage1e_json(frozen_snapshot),
                now, validated_at,
            ),
        )

        _db_append_audit(
            conn,
            entity_type="WalletAssessment",
            entity_id=assessment_id,
            relationship_id=rel["id"],
            event_type="STRUCTURAL_LENDING_ASSESSMENT_CREATED",
            actor=actor,
            payload={
                "methodology": "STRUCTURAL_LENDING 1.0",
                "wallet_coverage": snapshot["wallet_coverage"],
                "component_status": snapshot["component_status"],
                "addressable_notional": snapshot["addressable_structural_lending_notional"],
                "currency": currency,
                "publication_result": snapshot["publication_result"],
                "test_only": bool(assessment_input.test_only),
            },
        )
        if status == AssessmentStatus.VALIDATED.value:
            _db_append_audit(
                conn,
                entity_type="WalletAssessment",
                entity_id=assessment_id,
                relationship_id=rel["id"],
                event_type="STRUCTURAL_LENDING_ASSESSMENT_VALIDATED",
                actor=actor,
                payload={
                    "wallet_coverage": snapshot["wallet_coverage"],
                    "warnings": snapshot["warnings"],
                    "publication_result": snapshot["publication_result"],
                    "test_only": bool(assessment_input.test_only),
                },
            )

    return _db_stage1e_get_assessment(assessment_id)


def _db_stage1e2_latest_assessment(company: str) -> dict | None:
    conn = _db_connect()
    try:
        rel = _db_relationship_row(conn, company)
        row = conn.execute(
            """SELECT wa.assessment_id
               FROM wallet_assessment wa
               JOIN intelligence_methodology im ON im.id=wa.methodology_id
               WHERE wa.relationship_id=? AND im.methodology_code='STRUCTURAL_LENDING'
                 AND im.version='1.0'
               ORDER BY wa.id DESC LIMIT 1""",
            (rel["id"],),
        ).fetchone()
        assessment_id = row["assessment_id"] if row is not None else None
    finally:
        conn.close()
    return _db_stage1e_get_assessment(assessment_id) if assessment_id else None



def _stage1e2_parse_json_list(value) -> list[str]:
    """Safely parse the persisted evidence/calculation ID arrays."""
    if value is None:
        return []
    if isinstance(value, (list, tuple)):
        return [str(x) for x in value]
    try:
        parsed = json.loads(str(value))
    except Exception:
        return []
    if not isinstance(parsed, list):
        return []
    return [str(x) for x in parsed]


def _db_stage1e2_get_lineage(assessment_id: str) -> dict:
    """Read-only lineage inspector for a persisted WalletAssessment.

    This function performs no INSERT/UPDATE/DELETE. It is intentionally limited
    to the assessment's frozen evidence IDs, calculation IDs and append-only
    WalletAssessment audit events.
    """
    conn = _db_connect()
    try:
        wa = conn.execute(
            """SELECT wa.*, r.name AS relationship_name,
                      im.methodology_code, im.version AS methodology_version
               FROM wallet_assessment wa
               JOIN relationship r ON r.id=wa.relationship_id
               JOIN intelligence_methodology im ON im.id=wa.methodology_id
               WHERE wa.assessment_id=?""",
            (assessment_id,),
        ).fetchone()
        if wa is None:
            raise ValueError(f"Wallet assessment {assessment_id} not found.")

        evidence_ids = _stage1e2_parse_json_list(wa["evidence_ids_json"])
        calculation_ids = _stage1e2_parse_json_list(wa["calculation_ids_json"])

        evidence_rows = []
        for evidence_id in evidence_ids:
            r = conn.execute(
                """SELECT evidence_id,metric_code,metric_name,value_numeric,value_text,
                          unit,currency,evidence_type,source_type,source_name,
                          source_reference,effective_date,as_of_date,confidence,
                          economic_perimeter,geographic_scope,time_basis,rationale,created_at
                   FROM intelligence_evidence WHERE evidence_id=?""",
                (evidence_id,),
            ).fetchone()
            if r is not None:
                evidence_rows.append({
                    "Evidence ID": r["evidence_id"],
                    "Metric": r["metric_code"],
                    "Metric Name": r["metric_name"] or "",
                    "Numeric Value": r["value_numeric"],
                    "Text Value": r["value_text"],
                    "Unit": r["unit"] or "",
                    "Currency": r["currency"] or "",
                    "Type": r["evidence_type"],
                    "Source Type": r["source_type"] or "",
                    "Source": r["source_name"] or "",
                    "Source Reference": r["source_reference"] or "",
                    "Confidence": r["confidence"],
                    "Economic Perimeter": r["economic_perimeter"] or "",
                    "Geographic Scope": r["geographic_scope"] or "",
                    "Time Basis": r["time_basis"] or "",
                    "Rationale": r["rationale"] or "",
                    "Created": r["created_at"],
                })

        calculation_rows = []
        for calculation_id in calculation_ids:
            r = conn.execute(
                """SELECT calculation_id,metric_code,formula_code,formula_version,
                          formula_expression,input_evidence_ids_json,output_value_numeric,
                          unit,currency,calculated_at
                   FROM intelligence_calculation WHERE calculation_id=?""",
                (calculation_id,),
            ).fetchone()
            if r is not None:
                calculation_rows.append({
                    "Calculation ID": r["calculation_id"],
                    "Metric": r["metric_code"],
                    "Formula": r["formula_code"],
                    "Formula Version": r["formula_version"],
                    "Expression": r["formula_expression"],
                    "Input Evidence IDs": _stage1e2_parse_json_list(r["input_evidence_ids_json"]),
                    "Output": r["output_value_numeric"],
                    "Unit": r["unit"] or "",
                    "Currency": r["currency"] or "",
                    "Calculated": r["calculated_at"],
                })

        audit_rows_raw = conn.execute(
            """SELECT audit_event_id,event_type,event_timestamp,actor,payload_json
               FROM audit_event
               WHERE entity_type='WalletAssessment' AND entity_id=?
               ORDER BY id""",
            (assessment_id,),
        ).fetchall()
        audit_rows = []
        for r in audit_rows_raw:
            try:
                payload = json.loads(r["payload_json"] or "{}")
            except Exception:
                payload = {"raw": r["payload_json"]}
            audit_rows.append({
                "Audit Event ID": r["audit_event_id"],
                "Event": r["event_type"],
                "Timestamp": r["event_timestamp"],
                "Actor": r["actor"] or "",
                "Payload": payload,
            })

        return {
            "Assessment": {
                "Assessment ID": wa["assessment_id"],
                "Relationship": wa["relationship_name"],
                "Methodology": f"{wa['methodology_code']} {wa['methodology_version']}",
                "Status": wa["status"],
                "Publication Result": wa["publication_result"] or "",
                "Wallet Coverage": wa["wallet_coverage"] or "",
                "Evidence IDs": evidence_ids,
                "Calculation IDs": calculation_ids,
                "Test Only": bool(wa["test_only"]),
            },
            "Evidence": evidence_rows,
            "Calculations": calculation_rows,
            "Audit Events": audit_rows,
        }
    finally:
        conn.close()



def _stage1e2_toyota_persistence_fixture() -> tuple[StructuralLendingAssessmentInput, list[EvidenceItem]]:
    """Controlled TEST fixture. Never represents Toyota production truth."""
    evidence = [
        EvidenceItem(
            metric_code=FORECAST_CAPEX,
            metric_name="Forecast Capex",
            value_numeric=2_300_000_000_000,
            currency="JPY",
            evidence_type=EvidenceType.FACT,
            source_type="COMPANY_DISCLOSURE",
            source_name="Toyota FY2027 guidance — controlled test fixture",
            source_reference="Stage 1-E.2A.7 controlled test",
            confidence=ConfidenceLevel.HIGH,
        ),
        EvidenceItem(
            metric_code=FORECAST_CAPEX_DEBT_FUNDING_PCT,
            metric_name="Forecast Capex Debt Funding %",
            value_numeric=0.25,
            unit="PERCENT",
            evidence_type=EvidenceType.ASSUMPTION,
            source_type="SCENARIO_ASSUMPTION",
            source_name="25% controlled TEST assumption — not Toyota guidance",
            source_reference="Stage 1-E.2A.7 controlled test",
            confidence=ConfidenceLevel.MEDIUM,
        ),
        EvidenceItem(
            metric_code=FORECAST_BANK_CAPEX_SHARE,
            metric_name="Forecast Bank Capex Share",
            value_numeric=0.657,
            unit="PERCENT",
            evidence_type=EvidenceType.DERIVED_FACT,
            source_type="MODEL_DERIVATION",
            source_name="65.7% historical parent bank-debt-share proxy — not management forecast",
            source_reference="Stage 1-E.2A.7 controlled test",
            confidence=ConfidenceLevel.MEDIUM,
        ),
    ]
    capex = StructuralLendingComponent(
        base_amount=2_300_000_000_000,
        funding_rate=0.25,
        bank_share=0.657,
        economic_perimeter="TOYOTA_PARENT",
        time_horizon="3Y",
        currency="JPY",
        evidence_ids=(FORECAST_CAPEX, FORECAST_CAPEX_DEBT_FUNDING_PCT, FORECAST_BANK_CAPEX_SHARE),
        estimation_method="Company capex fact + governed debt-funding scenario + historical parent bank-share proxy",
        rationale="Controlled persistence test of Structural Lending v1.0; refinancing and internal capture remain unassessed.",
        confidence="MEDIUM",
        financing_need_ids=("TOYOTA-FY2027-CAPEX",),
        assessed=True,
    )
    return StructuralLendingAssessmentInput(
        capex=capex,
        refinancing=None,
        capture=None,
        test_only=True,
    ), evidence


def _db_stage1e2_run_toyota_persistence_test(*, actor: str = "Founder Test") -> dict:
    assessment_input, evidence = _stage1e2_toyota_persistence_fixture()
    return _db_stage1e2_create_structural_assessment(
        "Toyota",
        assessment_input,
        evidence,
        effective_date="FY2027",
        currency="JPY",
        geographic_scope="Global",
        time_horizon="3Y",
        actor=actor,
    )

# END STAGE 1-E.2A.7 — STRUCTURAL LENDING v1.0 PERSISTENCE INTEGRATION



# =============================================================================
# STAGE 1-E.2B.6 — CASH & LIQUIDITY WALLET v1.0 / PERSISTENCE INTEGRATION
# =============================================================================
# The deterministic engine remains narrow by design: LIQUIDITY_BALANCE_ONLY.
# It does not estimate the full transaction-banking wallet. Payments, collections,
# trade, fee wallet and FX-linked operating flows remain outside v1.0.
#
# Governing rules:
#   - NULL is unknown; zero is verified zero.
#   - Addressable liquidity and internal capture are separate concepts.
#   - Deposit penetration is calculated only when scope/currency/time are comparable.
#   - Wallet gap is evidence, not a management recommendation.
#   - TEST-only assessments can be VALIDATED but never production-published.

RELEVANT_CASH_POOL = "RELEVANT_CASH_POOL"
FORECAST_BANKABLE_LIQUIDITY_SHARE = "FORECAST_BANKABLE_LIQUIDITY_SHARE"
OBSERVED_BANKABLE_LIQUIDITY_SHARE = "OBSERVED_BANKABLE_LIQUIDITY_SHARE"
OUR_AVERAGE_DEPOSITS = "OUR_AVERAGE_DEPOSITS"

ADDRESSABLE_LIQUIDITY_NOTIONAL = "ADDRESSABLE_LIQUIDITY_NOTIONAL"
DEPOSIT_PENETRATION = "DEPOSIT_PENETRATION"
RAW_DEPOSIT_GAP = "RAW_DEPOSIT_GAP"
POSITIVE_DEPOSIT_GAP = "POSITIVE_DEPOSIT_GAP"


class CashLiquidityComponentStatus(str, Enum):
    COMPLETE = "COMPLETE"
    PARTIAL = "PARTIAL"
    NOT_ASSESSED = "NOT_ASSESSED"
    INVALID = "INVALID"


CASH_LIQUIDITY_CRITICAL_METRICS = (
    RELEVANT_CASH_POOL,
    FORECAST_BANKABLE_LIQUIDITY_SHARE,
)


def _stage1e2b_norm(value: str | None) -> str:
    return (value or "").strip().casefold()


def _stage1e2b_time_basis_comparable(
    liquidity_basis: str | None,
    capture_basis: str | None,
) -> bool:
    if not liquidity_basis or not capture_basis:
        return False
    compatible = {
        ("average", "average"),
        ("normalized_average", "average"),
        ("forecast_average", "forecast_average"),
        ("period_end", "period_end"),
    }
    return (
        _stage1e2b_norm(liquidity_basis),
        _stage1e2b_norm(capture_basis),
    ) in compatible


def _stage1e2b_evaluate_cash_liquidity(
    evidence: list[EvidenceItem],
    *,
    test_only: bool = False,
) -> tuple[dict, list[CalculationRecord]]:
    """Deterministic Cash & Liquidity Wallet v1.0; no persistence side effects."""
    ev = _stage1e_evidence_map(evidence)
    calculations: list[CalculationRecord] = []
    warnings: list[str] = []
    blockers: list[str] = []

    cash_item = ev.get(RELEVANT_CASH_POOL)
    share_item = ev.get(FORECAST_BANKABLE_LIQUIDITY_SHARE)
    capture_item = ev.get(OUR_AVERAGE_DEPOSITS)

    missing = [m for m in CASH_LIQUIDITY_CRITICAL_METRICS if m not in ev]
    if missing:
        blockers.append("MISSING_CRITICAL_EVIDENCE: " + ", ".join(missing))

    for item in (cash_item, share_item):
        if item is not None and (not item.source_type or not item.source_name):
            blockers.append(f"MISSING_CRITICAL_PROVENANCE: {item.metric_code}")

    cash = _stage1e_numeric(ev, RELEVANT_CASH_POOL)
    bankable_share = _stage1e_numeric(ev, FORECAST_BANKABLE_LIQUIDITY_SHARE)

    if cash_item is not None and cash is None:
        blockers.append("RELEVANT_CASH_POOL_NON_NUMERIC")
    if share_item is not None and bankable_share is None:
        blockers.append("FORECAST_BANKABLE_LIQUIDITY_SHARE_NON_NUMERIC")
    if cash is not None and cash < 0:
        blockers.append("RELEVANT_CASH_POOL_NEGATIVE")
    if bankable_share is not None and not 0 <= bankable_share <= 1:
        blockers.append("FORECAST_BANKABLE_LIQUIDITY_SHARE_OUT_OF_RANGE")

    if cash_item is not None and share_item is not None:
        for code, left, right in (
            ("SCOPE_MISMATCH", cash_item.economic_perimeter, share_item.economic_perimeter),
            ("GEOGRAPHIC_SCOPE_MISMATCH", cash_item.geographic_scope, share_item.geographic_scope),
            ("TIME_BASIS_MISMATCH", cash_item.time_basis, share_item.time_basis),
        ):
            if left and right and _stage1e2b_norm(left) != _stage1e2b_norm(right):
                blockers.append(code)

    confidence, confidence_explanation = _stage1e_derive_confidence(
        evidence,
        critical_metrics=CASH_LIQUIDITY_CRITICAL_METRICS,
    )

    liquidity_status = (
        CashLiquidityComponentStatus.INVALID.value
        if blockers
        else CashLiquidityComponentStatus.COMPLETE.value
    )
    addressable = None
    if not blockers and cash is not None and bankable_share is not None:
        addressable = float(cash) * float(bankable_share)
        calculations.append(CalculationRecord(
            metric_code=ADDRESSABLE_LIQUIDITY_NOTIONAL,
            formula_code="CASH_LIQUIDITY_001",
            formula_version="1.0",
            formula_expression="RELEVANT_CASH_POOL * FORECAST_BANKABLE_LIQUIDITY_SHARE",
            input_metric_codes=(RELEVANT_CASH_POOL, FORECAST_BANKABLE_LIQUIDITY_SHARE),
            output_value_numeric=addressable,
            unit="MONEY",
            currency=cash_item.currency if cash_item else None,
        ))

    capture_status = CashLiquidityComponentStatus.NOT_ASSESSED.value
    capture_comparability = CaptureComparabilityStatus.NOT_ASSESSED.value
    capture_reason = "Internal deposit capture evidence is not available."
    capture = _stage1e_numeric(ev, OUR_AVERAGE_DEPOSITS)
    penetration = None
    raw_gap = None
    positive_gap = None

    if capture_item is not None:
        if capture is None or capture < 0:
            capture_status = CashLiquidityComponentStatus.INVALID.value
            warnings.append("CAPTURE_EVIDENCE_INVALID")
        else:
            capture_status = CashLiquidityComponentStatus.COMPLETE.value
            missing_meta = []
            if not capture_item.source_type or not capture_item.source_name:
                missing_meta.append("provenance")
            if not capture_item.currency:
                missing_meta.append("currency")
            if not capture_item.economic_perimeter:
                missing_meta.append("economic perimeter")
            if not capture_item.geographic_scope:
                missing_meta.append("geographic scope")
            if not capture_item.time_basis:
                missing_meta.append("time basis")

            if missing_meta:
                capture_comparability = CaptureComparabilityStatus.NOT_COMPARABLE.value
                capture_reason = "Capture evidence missing " + ", ".join(missing_meta) + "."
            elif cash_item and cash_item.currency and _stage1e2b_norm(cash_item.currency) != _stage1e2b_norm(capture_item.currency):
                capture_comparability = CaptureComparabilityStatus.NOT_COMPARABLE.value
                capture_reason = f"Currency mismatch: wallet {cash_item.currency} vs capture {capture_item.currency}."
            elif cash_item and cash_item.economic_perimeter and _stage1e2b_norm(cash_item.economic_perimeter) != _stage1e2b_norm(capture_item.economic_perimeter):
                capture_comparability = CaptureComparabilityStatus.NOT_COMPARABLE.value
                capture_reason = "Economic perimeter mismatch between wallet and internal deposits."
            elif cash_item and cash_item.geographic_scope and _stage1e2b_norm(cash_item.geographic_scope) != _stage1e2b_norm(capture_item.geographic_scope):
                capture_comparability = CaptureComparabilityStatus.NOT_COMPARABLE.value
                capture_reason = "Geographic scope mismatch between wallet and internal deposits."
            elif cash_item and not _stage1e2b_time_basis_comparable(cash_item.time_basis, capture_item.time_basis):
                capture_comparability = CaptureComparabilityStatus.NOT_COMPARABLE.value
                capture_reason = f"Time basis mismatch: wallet {cash_item.time_basis or 'N/A'} vs capture {capture_item.time_basis or 'N/A'}."
            else:
                capture_comparability = CaptureComparabilityStatus.COMPARABLE.value
                capture_reason = "Internal deposits are economically comparable to the wallet denominator."

            if capture_comparability != CaptureComparabilityStatus.COMPARABLE.value:
                warnings.append("CAPTURE_NOT_COMPARABLE")

    if (
        addressable is not None
        and capture is not None
        and capture >= 0
        and capture_comparability == CaptureComparabilityStatus.COMPARABLE.value
    ):
        if addressable > 0:
            penetration = float(capture) / float(addressable)
            calculations.append(CalculationRecord(
                metric_code=DEPOSIT_PENETRATION,
                formula_code="CASH_CAPTURE_001",
                formula_version="1.0",
                formula_expression="OUR_AVERAGE_DEPOSITS / ADDRESSABLE_LIQUIDITY_NOTIONAL",
                input_metric_codes=(OUR_AVERAGE_DEPOSITS, ADDRESSABLE_LIQUIDITY_NOTIONAL),
                output_value_numeric=penetration,
                unit="RATIO",
                currency=None,
            ))
        raw_gap = float(addressable) - float(capture)
        positive_gap = max(0.0, raw_gap)
        calculations.append(CalculationRecord(
            metric_code=RAW_DEPOSIT_GAP,
            formula_code="CASH_GAP_001",
            formula_version="1.0",
            formula_expression="ADDRESSABLE_LIQUIDITY_NOTIONAL - OUR_AVERAGE_DEPOSITS",
            input_metric_codes=(OUR_AVERAGE_DEPOSITS,),
            output_value_numeric=raw_gap,
            unit="MONEY",
            currency=cash_item.currency if cash_item else None,
        ))
        calculations.append(CalculationRecord(
            metric_code=POSITIVE_DEPOSIT_GAP,
            formula_code="CASH_GAP_002",
            formula_version="1.0",
            formula_expression="MAX(0, RAW_DEPOSIT_GAP)",
            input_metric_codes=(OUR_AVERAGE_DEPOSITS,),
            output_value_numeric=positive_gap,
            unit="MONEY",
            currency=cash_item.currency if cash_item else None,
        ))
        if capture > addressable:
            warnings.append("CAPTURE_EXCEEDS_ESTIMATED_WALLET")

    if confidence == ConfidenceLevel.LOW:
        warnings.append("LOW_CONFIDENCE_CRITICAL_ASSUMPTION")
    if cash_item and _stage1e2b_norm(cash_item.time_basis) == "period_end":
        warnings.append("POINT_IN_TIME_ONLY")
    if test_only:
        warnings.append("TEST_ONLY_NOT_FOR_PRODUCTION")

    warnings = sorted(set(warnings))
    blockers = sorted(set(blockers))
    hold_codes = {
        "LOW_CONFIDENCE_CRITICAL_ASSUMPTION",
        "POINT_IN_TIME_ONLY",
        "CAPTURE_EXCEEDS_ESTIMATED_WALLET",
        "TEST_ONLY_NOT_FOR_PRODUCTION",
    }

    if blockers:
        publication_result = PublicationResult.REJECT.value
    elif any(code in hold_codes for code in warnings):
        publication_result = PublicationResult.HOLD.value
    else:
        publication_result = PublicationResult.PUBLISH.value

    snapshot = {
        "methodology_code": "CASH_LIQUIDITY_WALLET",
        "methodology_version": "1.0",
        "methodology_scope": "LIQUIDITY_BALANCE_ONLY",
        "wallet_coverage": "LIQUIDITY_BALANCE_ONLY" if addressable is not None else "NOT_ASSESSED",
        "liquidity_component_status": liquidity_status,
        "capture_component_status": capture_status,
        "relevant_cash_pool": cash,
        "forecast_bankable_liquidity_share": bankable_share,
        "addressable_liquidity_notional": addressable,
        "comparable_capture_notional": capture if capture_comparability == CaptureComparabilityStatus.COMPARABLE.value else None,
        "deposit_penetration": penetration,
        "raw_deposit_gap": raw_gap,
        "positive_deposit_gap": positive_gap,
        "capture_comparability_status": capture_comparability,
        "capture_comparability_reason": capture_reason,
        "currency": cash_item.currency if cash_item else None,
        "economic_perimeter": cash_item.economic_perimeter if cash_item else None,
        "geographic_scope": cash_item.geographic_scope if cash_item else None,
        "liquidity_time_basis": cash_item.time_basis if cash_item else None,
        "effective_date": cash_item.effective_date if cash_item else None,
        "confidence": confidence.value if confidence else None,
        "confidence_explanation": confidence_explanation,
        "warnings": warnings,
        "blocking_issues": blockers,
        "publication_result": publication_result,
        "production_publication_allowed": publication_result == PublicationResult.PUBLISH.value and not test_only,
        "test_only": bool(test_only),
    }
    return snapshot, calculations


def _db_seed_stage1e2b_methodology(conn: _DBConnection):
    """Idempotently register Cash & Liquidity Wallet v1.0."""
    existing = conn.execute(
        """SELECT * FROM intelligence_methodology
           WHERE methodology_code=? AND version=?""",
        ("CASH_LIQUIDITY_WALLET", "1.0"),
    ).fetchone()
    if existing is not None:
        return existing

    methodology_id = _db_next_id(
        conn, "intelligence_methodology", "methodology_id", "MTH"
    )
    now = _db_now()
    conn.execute(
        """INSERT INTO intelligence_methodology(
               methodology_id,methodology_code,methodology_name,version,domain,product,
               description,required_inputs_json,optional_inputs_json,outputs_json,
               critical_inputs_json,effective_from,status,created_at,updated_at
           ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            methodology_id,
            "CASH_LIQUIDITY_WALLET",
            "Cash & Liquidity Wallet v1.0 — Liquidity Balance Scope",
            "1.0",
            "WALLET",
            "CASH_LIQUIDITY",
            "Bank-addressable liquidity balances derived from a governed relevant cash pool and forecast bankable liquidity share; transaction-banking fee wallet remains outside scope.",
            _stage1e_json(list(CASH_LIQUIDITY_CRITICAL_METRICS)),
            _stage1e_json([OBSERVED_BANKABLE_LIQUIDITY_SHARE, OUR_AVERAGE_DEPOSITS]),
            _stage1e_json([
                ADDRESSABLE_LIQUIDITY_NOTIONAL,
                DEPOSIT_PENETRATION,
                RAW_DEPOSIT_GAP,
                POSITIVE_DEPOSIT_GAP,
            ]),
            _stage1e_json(list(CASH_LIQUIDITY_CRITICAL_METRICS)),
            now,
            "ACTIVE",
            now,
            now,
        ),
    )
    return conn.execute(
        "SELECT * FROM intelligence_methodology WHERE methodology_id=?",
        (methodology_id,),
    ).fetchone()


def _db_stage1e2b_create_cash_assessment(
    company: str,
    evidence: list[EvidenceItem],
    *,
    effective_date: str | None = None,
    geographic_scope: str = "Global",
    time_horizon: str = "1Y",
    test_only: bool = False,
    actor: str = "EC-AI",
) -> dict:
    """Persist a frozen Cash & Liquidity Wallet v1.0 assessment; never auto-publish."""
    snapshot, calculations = _stage1e2b_evaluate_cash_liquidity(
        evidence,
        test_only=test_only,
    )
    evidence_map = _stage1e_evidence_map(evidence)
    missing = [m for m in CASH_LIQUIDITY_CRITICAL_METRICS if m not in evidence_map]
    if missing:
        raise ValueError(
            "Cash & Liquidity persistence refused — missing critical evidence: "
            + ", ".join(missing)
        )

    with _db_transaction() as conn:
        methodology = _db_seed_stage1e2b_methodology(conn)
        cycle = _db_active_review_cycle(conn)
        rel = _db_relationship_row(conn, company)

        evidence_ids = []
        evidence_by_metric = {}
        for item in evidence:
            evidence_id = _db_stage1e_persist_evidence(
                conn,
                relationship_db_id=rel["id"],
                review_cycle_db_id=cycle["id"],
                methodology_db_id=methodology["id"],
                item=item,
            )
            evidence_ids.append(evidence_id)
            evidence_by_metric[item.metric_code] = evidence_id

        calculation_ids = []
        for calc in calculations:
            input_ids = [
                evidence_by_metric[m]
                for m in calc.input_metric_codes
                if m in evidence_by_metric
            ]
            calc_id = _db_stage1e_persist_calculation(
                conn,
                relationship_db_id=rel["id"],
                review_cycle_db_id=cycle["id"],
                methodology_db_id=methodology["id"],
                record=calc,
                input_evidence_ids=input_ids,
            )
            calculation_ids.append(calc_id)

        frozen_snapshot = dict(snapshot)
        frozen_snapshot["evidence_ids"] = list(evidence_ids)
        frozen_snapshot["calculation_ids"] = list(calculation_ids)
        frozen_snapshot["effective_date"] = effective_date or snapshot.get("effective_date")
        frozen_snapshot["geographic_scope"] = geographic_scope or snapshot.get("geographic_scope")
        frozen_snapshot["time_horizon"] = time_horizon

        assessment_id = _db_next_id(
            conn, "wallet_assessment", "assessment_id", "WAL"
        )
        now = _db_now()
        status = (
            AssessmentStatus.DRAFT.value
            if snapshot["publication_result"] == PublicationResult.REJECT.value
            else AssessmentStatus.VALIDATED.value
        )
        validated_at = now if status == AssessmentStatus.VALIDATED.value else None
        notional_completeness = (
            CompletenessStatus.COMPLETE.value
            if snapshot["liquidity_component_status"] == CashLiquidityComponentStatus.COMPLETE.value
            else CompletenessStatus.PARTIAL.value
        )
        quality_gate = {
            "methodology": "CASH_LIQUIDITY_WALLET 1.0",
            "methodology_scope": snapshot["methodology_scope"],
            "wallet_coverage": snapshot["wallet_coverage"],
            "warnings": snapshot["warnings"],
            "blocking_issues": snapshot["blocking_issues"],
            "publication_result": snapshot["publication_result"],
            "production_publication_allowed": snapshot["production_publication_allowed"],
            "test_only": bool(test_only),
        }

        conn.execute(
            """INSERT INTO wallet_assessment(
                   assessment_id,relationship_id,review_cycle_id,methodology_id,
                   product,effective_date,currency,geographic_scope,time_horizon,
                   evidence_ids_json,calculation_ids_json,
                   addressable_notional,captured_notional,notional_penetration,
                   estimated_wallet_revenue,actual_bank_revenue,revenue_share_of_wallet,
                   revenue_wallet_gap,notional_completeness,revenue_wallet_completeness,
                   confidence,confidence_explanation,status,publication_result,
                   quality_gate_json,wallet_scope,wallet_coverage,
                   capex_component_status,refinancing_component_status,capture_component_status,
                   bank_capex_notional,bank_refinancing_notional,raw_wallet_gap,positive_wallet_gap,
                   capture_comparability_status,test_only,economic_interpretation_json,
                   liquidity_component_status,relevant_cash_pool,
                   forecast_bankable_liquidity_share,liquidity_time_basis,
                   created_at,validated_at
               ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                assessment_id, rel["id"], cycle["id"], methodology["id"],
                "CASH_LIQUIDITY", effective_date or snapshot.get("effective_date"),
                snapshot.get("currency"), geographic_scope, time_horizon,
                _stage1e_json(evidence_ids), _stage1e_json(calculation_ids),
                snapshot["addressable_liquidity_notional"],
                snapshot["comparable_capture_notional"], snapshot["deposit_penetration"],
                None, None, None, None,
                notional_completeness, CompletenessStatus.PARTIAL.value,
                snapshot["confidence"], snapshot["confidence_explanation"],
                status, snapshot["publication_result"], _stage1e_json(quality_gate),
                snapshot["methodology_scope"], snapshot["wallet_coverage"],
                None, None, snapshot["capture_component_status"],
                None, None, snapshot["raw_deposit_gap"], snapshot["positive_deposit_gap"],
                snapshot["capture_comparability_status"], 1 if test_only else 0,
                _stage1e_json(frozen_snapshot), snapshot["liquidity_component_status"],
                snapshot["relevant_cash_pool"], snapshot["forecast_bankable_liquidity_share"],
                snapshot["liquidity_time_basis"], now, validated_at,
            ),
        )

        _db_append_audit(
            conn,
            entity_type="WalletAssessment",
            entity_id=assessment_id,
            relationship_id=rel["id"],
            event_type="CASH_LIQUIDITY_ASSESSMENT_CREATED",
            actor=actor,
            payload={
                "methodology": "CASH_LIQUIDITY_WALLET 1.0",
                "methodology_scope": snapshot["methodology_scope"],
                "addressable_notional": snapshot["addressable_liquidity_notional"],
                "currency": snapshot.get("currency"),
                "liquidity_time_basis": snapshot.get("liquidity_time_basis"),
                "publication_result": snapshot["publication_result"],
                "test_only": bool(test_only),
            },
        )
        if status == AssessmentStatus.VALIDATED.value:
            _db_append_audit(
                conn,
                entity_type="WalletAssessment",
                entity_id=assessment_id,
                relationship_id=rel["id"],
                event_type="CASH_LIQUIDITY_ASSESSMENT_VALIDATED",
                actor=actor,
                payload={
                    "warnings": snapshot["warnings"],
                    "publication_result": snapshot["publication_result"],
                    "test_only": bool(test_only),
                },
            )

    return _db_stage1e_get_assessment(assessment_id)


def _db_stage1e2b_latest_assessment(company: str) -> dict | None:
    conn = _db_connect()
    try:
        rel = _db_relationship_row(conn, company)
        row = conn.execute(
            """SELECT wa.assessment_id
               FROM wallet_assessment wa
               JOIN intelligence_methodology im ON im.id=wa.methodology_id
               WHERE wa.relationship_id=? AND im.methodology_code='CASH_LIQUIDITY_WALLET'
                 AND im.version='1.0'
               ORDER BY wa.id DESC LIMIT 1""",
            (rel["id"],),
        ).fetchone()
        assessment_id = row["assessment_id"] if row is not None else None
    finally:
        conn.close()
    return _db_stage1e_get_assessment(assessment_id) if assessment_id else None


