E4_9_PREVIOUS_PUBLICATION_MODE = "E4.9_VALIDATION_PREVIOUS"
E4_9_CURRENT_PUBLICATION_MODE = "E4.9_VALIDATION_CURRENT"
E4_9_EVENT_SOURCE_REFERENCE = "E4.9-DEBT-MATURITY-EVIDENCE"
